// Anfrage lesen: Sitzungs-Token aus dem Cookie, Meldungscode, Ansicht und Thema aus der Adresse
const h = $json.headers || {};
const kekse = String(h.cookie || '').split(';').map(x => x.trim());
const roh = (kekse.find(x => x.startsWith('ally_sitzung=')) || '').slice('ally_sitzung='.length);
// Neue Oberfläche Teil B (Stefan 19.10.2026): Talents verwalten gehört zum Bereich Talents. Alte Adressen unter Einstellungen › Talents mit Talent, Einladen,
// Einladung, Import, Archiv, Filter oder Seite führen auf dieselben Ansichten im Bereich Talents (ansicht=talents; Talent -> b=stammdaten, ts=archiviert -> status=archiviert,
// tq -> suche). Ohne diese Angaben bzw. mit tm=standards, ki, ablage bleibt es bei Einstellungen › Talents (nur Konfigurationen).
const q0 = $json.query || {};
const altTl = String(q0.ansicht || '') === 'einstellungen' && String(q0.bereich || '') === 'talents' && !['standards', 'ki', 'ablage'].includes(String(q0.tm ?? '').trim()) &&
  ['talent', 'tm', 'ts', 'tq', 'status', 'person', 'suche', 'seite', 'import', 'nur_fehler'].some(k => String(q0[k] ?? '').trim() !== '');
const q = altTl ? Object.assign({}, q0, { ansicht: 'talents', bereich: '',
  status: String(q0.status ?? '').trim() || (String(q0.ts ?? '').trim() === 'archiviert' ? 'archiviert' : ''), suche: String(q0.suche ?? '').trim() || String(q0.tq ?? '').trim(),
  b: /^[0-9]{1,9}$/.test(String(q0.talent ?? '').trim()) && String(q0.tm ?? '').trim() !== 'einladung' ? 'stammdaten' : '' }) : q0;
// Ansicht: Startseite (leer), Monatsbericht, Einstellungen, Passwort vergessen oder Neues Passwort (Link aus der Mail)
// Unternehmen, Marketing, Eigener Speicherort und jedes Zusatzpaket haben eigene Seiten (Ansicht = Schlüssel des Pakets).
// Alte Links: Einstellungen › Unternehmen und › Instagram führen zu Unternehmen bzw. Marketing, › Ally-Funktionen zu den Benachrichtigungen, › Meine Einstellungen zur Startseite.
const PAKET_SEITEN = ['morgen_briefing', 'mail_entwuerfe', 'belege', 'zeiterfassung'];
// Masken der Startseite (Belege verbuchen, Abgleich, Marketing-Beiträge, Kundenüberblick, Briefing, Mails, Kalender, Projektbudgets, System-Mails, Ally fragen)
const MASKEN = ['belege_verbuchen', 'abgleich', 'beitrag', 'kundenueberblick', 'briefing', 'mails', 'kalender', 'budgets', 'systemmails', 'fragen'];
// Talents (Stefan 18.10.2026): eigene Hauptansicht ansicht=talents (Übersicht, Talent, Beiträge, Beitrag)
// Kampagnen (Stefan 18.10.2026), Migration 46: eigene Hauptansicht ansicht=kampagnen (Liste, Seite je Kampagne, Neu/Bearbeiten, Beiträge zuordnen)
const a0 = ['monatsbericht', 'einstellungen', 'verbrauch', 'vergessen', 'neu', 'unternehmen', 'marketing', 'speicherort', 'talents', 'kampagnen'].concat(PAKET_SEITEN, MASKEN).includes(String(q.ansicht || '')) ? String(q.ansicht) : '';
const alt = { zugang: 'profil', funktionen: 'benachrichtigungen', meine: 'startseite' };
const b0 = alt[String(q.bereich || '')] || String(q.bereich || '');
// Marketing veröffentlichen steht auf der Seite Marketing (auch alte Links auf den Instagram-Zugang)
const ansicht = a0 === 'einstellungen' && b0 === 'unternehmen' ? 'unternehmen' : (a0 === 'einstellungen' && b0 === 'instagram') || String(q.ansicht || '') === 'marketing_posten' ? 'marketing' : a0;
// KI und Superadmin (Stefan 18.10.2026): Bereiche Einstellungen › KI und › Superadmin (Rechte prüfen Seite und Datenbank)
const bereich = ansicht === 'einstellungen' ? (['profil', 'startseite', 'benachrichtigungen', 'postfaecher', 'regeln', 'personen', 'paket', 'ki', 'superadmin', 'talents'].includes(b0) ? b0 : 'profil') : '';
const code = ansicht === 'neu' && /^[0-9a-f]{64}$/.test(String(q.code || '')) ? String(q.code) : '';
// offen: Unternehmen, das nach dem Speichern wieder aufgeklappt wird
const offen = /^[0-9]{1,9}$/.test(String(q.offen || '')) ? String(q.offen) : '';
// ordner: gewählter Ordner aus den Auswahllisten (Seiten Eigener Speicherort und Belege), nur ein gültiger Pfad
const o0 = String(q.ordner || '').trim().replace(/\/+$/, '') || (q.ordner !== undefined && String(q.ordner).trim().startsWith('/') ? '/' : '');
const ordner = o0.length <= 500 && /^\//.test(o0) && !/[\x00-\x1f\x7f*?{}]/.test(o0) && !/(^|\/)\.\.?(\/|$)/.test(o0) && !/\/\//.test(o0) ? o0 : '';
// p: Auswahl in den Arbeitsbereichen (Thema, Filter, Suche, Zeitraum), nur gültige Werte; prüft zusätzlich die Datenbank (arbeit_web_seite)
const sq = v => String(v ?? '').trim();
const p = {};
if (/^[0-9]{1,9}$/.test(sq(q.thema))) p.thema = sq(q.thema);
if (['vorschlag', 'entwurf', 'fertig', 'verworfen'].includes(sq(q.status))) p.status = sq(q.status);
if (sq(q.q)) p.q = sq(q.q).replace(/[\x00-\x1f\x7f]/g, '').slice(0, 100);
if (/^[0-9]{1,2}$/.test(sq(q.tage))) p.tage = sq(q.tage);
if (['kunde', 'geschaeft', 'keine', 'spam', 'system_report'].includes(sq(q.kategorie))) p.kategorie = sq(q.kategorie);
if (/^20[0-9]{2}-[01][0-9]-[0-3][0-9]$/.test(sq(q.von))) p.von = sq(q.von);
if (sq(q.suche) === '1') p.suche = '1';
// Teil C (Stefan 19.10.2026): Mails haben das Mail-Log als eigenen Reiter (ohne "Anzeigen"), es wird deshalb immer geladen
if (sq(q.log) === '1' || ansicht === 'mails') p.log = '1';
// Talents (Stefan 18.10.2026): Auswahl auf Einstellungen › Talents (gewähltes Talent, Suche, Statusfilter, Maske), nur gültige Werte; gefiltert wird in "Talents einsetzen"
const tl = {};
if (ansicht === 'einstellungen' && bereich === 'talents') {
  if (/^[0-9]{1,9}$/.test(sq(q.talent))) tl.talent = sq(q.talent);
  if (sq(q.tq)) tl.tq = sq(q.tq).replace(/[\x00-\x1f\x7f]/g, '').slice(0, 100);
  if (/^[a-z]{1,20}$/.test(sq(q.ts))) tl.ts = sq(q.ts);
  // Migration 46 (Stefan 18.10.2026): tm=import (Talents importieren) und tm=standards (Standards der Agentur)
  // Migration 49 (Stefan 18.10.2026): tm=ki (KI-Funktionen) und tm=ablage (Speicherort der Talents-Dateien), eigene Ansichten nur für Admins
  if (['neu', 'bearbeiten', 'import', 'standards', 'ki', 'ablage'].includes(sq(q.tm))) tl.tm = sq(q.tm);
}
// Talents-Seiten (Stefan 18.10.2026): ansicht=talents – Talent, Unteransicht (b=beitraege|beitrag), Beitrag und Filter aus der Adresse, nur gültige Werte.
// Welche Filter gelten, hängt von der Unteransicht ab (Übersicht: Zeitraum, Kanal, Person, Suche, Sortierung, Seite; Talent: Zeitraum, Kanal;
// Beiträge: Kanal, Art, Zeitraum, Sortierung, Seite; Beitrag: keine). Die Datenbank prüft Werte, Rechte und Zuständigkeit nochmals (Migration 44).
const tp = {};
// kanal: Plattform (z. B. instagram) oder ein einzelner Account als k<kanal_id> (vorbereitet für Migration 45, mehrere Accounts je Plattform)
if (ansicht === 'talents') {
  const filter = {};
  const nimm = (k, re) => { const v = sq(q[k]); if (v && re.test(v)) filter[k] = v; };
  const DATUM = /^[0-9]{1,4}[-.][0-9]{1,2}[-.][0-9]{1,4}$/;
  if (/^[0-9]{1,9}$/.test(sq(q.talent))) tp.talent = sq(q.talent);
  if (sq(q.b) === 'beitrag' && /^[0-9]{1,12}$/.test(sq(q.beitrag))) { tp.b = 'beitrag'; tp.beitrag = sq(q.beitrag); }
  else if (sq(q.b) === 'beitraege' && tp.talent) tp.b = 'beitraege';
  if (tp.b !== 'beitrag') {
    nimm('zeitraum', /^[a-z0-9]{1,12}$/); nimm('von', DATUM); nimm('bis', DATUM); nimm('kanal', /^([a-z_]{1,20}|k[0-9]{1,9})$/);
    if (!tp.talent) {
      const pe = sq(q.person); if (pe.length <= 255 && /^@[^\s:]{1,200}:[^\s]{1,200}$/.test(pe) && !/[\x00-\x1f\x7f]/.test(pe)) filter.person = pe;
      const su = sq(q.suche).replace(/[\x00-\x1f\x7f]/g, '').slice(0, 100).trim(); if (su) filter.suche = su;
    }
    if (!tp.talent || tp.b === 'beitraege') { nimm('sortierung', /^[a-z_]{1,20}$/); nimm('seite', /^[0-9]{1,4}$/); }
    if (tp.b === 'beitraege') nimm('art', /^[a-z]{1,12}$/);
  }
  tp.filter = filter;
}
// Migrationen 47 und 49 (Stefan 18.10.2026): weitere Unteransichten der Talents mit eigenem Baustein "Talents-Werkzeuge einsetzen":
// b=berichte, texte, anfrage (auch ohne Talent) und b=zahlen, konzept, wf, marken, mails (nur mit Talent). Ohne gültiges Talent bleibt es bei der Übersicht.
const WERKZEUG = ['berichte', 'zahlen', 'konzept', 'wf', 'marken', 'mails', 'texte', 'anfrage'];
if (ansicht === 'talents' && !tp.b && WERKZEUG.includes(sq(q.b)) && (tp.talent || ['berichte', 'texte', 'anfrage'].includes(sq(q.b)))) tp.b = sq(q.b);
// Teil B (Stefan 19.10.2026): Bereich Talents. tp.v = Ansicht zum Verwalten (liste, neu, import, stammdaten; "Talents einsetzen"), sonst wie bisher.
// - ohne Talent: Liste (Status, zuständig, Suche, Seite), tm=neu (Talent einladen), tm=import, b=rangliste (Zahlen aller Talents; auch alte Adressen mit Zeitraum, Kanal, Sortierung)
// - mit Talent: b=stammdaten (Kanäle, Einladung, Stammdaten; tm=einladung = Einladungslink), b=audience (Zielgruppe des Talents, Daten wie die Seite des Talents)
if (ansicht === 'talents' && !tp.b) {
  const tm = sq(q.tm), b0 = sq(q.b);
  if (tp.talent && (b0 === 'stammdaten' || tm === 'einladung')) { tp.b = 'stammdaten'; tp.v = 'stammdaten'; tp.filter = {}; if (tm === 'einladung') tp.tm = 'einladung'; }
  else if (tp.talent && b0 === 'audience') tp.b = 'audience';
  else if (!tp.talent && (tm === 'neu' || tm === 'import')) { tp.v = tm; tp.filter = {}; }
  else if (!tp.talent && (b0 === 'rangliste' || ['zeitraum', 'kanal', 'sortierung', 'von', 'bis'].some(k => sq(q[k])))) tp.b = 'rangliste';
  else if (!tp.talent) { tp.v = 'liste'; tp.filter = {}; } // unbekannte Unteransicht ohne Talent: Liste
}
// Stufe 2 (Stefan 18.10.2026), Migration 46: t2 = welche Daten "Seite laden" zusätzlich holt (Feld t2) und mit welchem Filter.
// Ohne Stufe-2-Daten (art leer) fehlt das Feld t2 ganz; "Seite laden" setzt dann '{}' ein.
// Nur geprüfte Werte (Zahlen nur als Ziffern, sonst gar nicht), damit die Datenbank-Aufrufe in "Seite laden" nie an Werten scheitern.
// Prüfen, Rechte und Grenzen (Seiten, Zuständigkeit) macht die Datenbank nochmals.
const t2 = { art: '' };
const zahl9 = v => /^[0-9]{1,9}$/.test(sq(v)) ? sq(v) : '';
const seite4 = v => /^[0-9]{1,4}$/.test(sq(v)) ? sq(v) : '';
const suche100 = v => sq(v).replace(/[\x00-\x1f\x7f]/g, '').slice(0, 100).trim();
const person = v => { const pe = sq(v); return pe.length <= 255 && /^@[^\s:]{1,200}:[^\s]{1,200}$/.test(pe) && !/[\x00-\x1f\x7f]/.test(pe) ? pe : ''; };
const ohneLeer = o => Object.fromEntries(Object.entries(o).filter(x => x[1] !== '' && x[1] !== undefined));
// Teil B (Stefan 19.10.2026): Liste und Import stehen im Bereich Talents (tp.v); Einstellungen › Talents braucht keine Liste mehr.
// Liste: Status (alte Adressen mit ts=archiviert zeigen die archivierten), zuständige Person, Suche, Seite (Seiten zu 20, "Seite laden" holt dafür zwei Seiten zu 10)
if (ansicht === 'talents' && tp.v === 'import') Object.assign(t2, { art: 'import', import: zahl9(q.import), filter: ohneLeer({ seite: seite4(q.seite), nur_fehler: sq(q.nur_fehler) === '1' ? '1' : '' }) });
if (ansicht === 'talents' && tp.v === 'liste') Object.assign(t2, { art: 'liste', filter: ohneLeer({ status: /^[a-z_]{1,30}$/.test(sq(q.status)) ? sq(q.status) : '', person: person(q.person), suche: suche100(q.suche), seite: seite4(q.seite) }) });
if (ansicht === 'talents' && tp.talent && !tp.b) Object.assign(t2, { art: 'talent', talent: tp.talent });
// Notizen eines Talents (b=notizen): eigene Ansicht mit Seiten
if (ansicht === 'talents' && tp.talent && sq(q.b) === 'notizen') { tp.b = 'notizen'; tp.filter = {}; Object.assign(t2, { art: 'notizen', talent: tp.talent, filter: ohneLeer({ seite: seite4(q.seite) }) }); }
if (ansicht === 'kampagnen') {
  const kid = zahl9(q.kampagne);
  if (kid && sq(q.b) === 'zuordnen') Object.assign(t2, { art: 'zuordnen', kampagne: kid, b: 'zuordnen',
    filter: ohneLeer({ talent: zahl9(q.talent), bereich: ['zeitraum', 'alle'].includes(sq(q.bereich)) ? sq(q.bereich) : '', seite: seite4(q.seite) }) });
  else if (kid && sq(q.b) === 'bearbeiten') Object.assign(t2, { art: 'kampagne', kampagne: kid, b: 'bearbeiten', filter: {} });
  else if (kid) Object.assign(t2, { art: 'kampagne', kampagne: kid, filter: ohneLeer({ tseite: seite4(q.tseite), vseite: seite4(q.vseite), bseite: seite4(q.bseite) }) });
  else if (sq(q.tm) === 'neu') Object.assign(t2, { art: 'kampagnen', tm: 'neu', filter: {} });
  else Object.assign(t2, { art: 'kampagnen', filter: ohneLeer({ status: ['laufend', 'geplant', 'beendet'].includes(sq(q.status)) ? sq(q.status) : '', talent: zahl9(q.talent), suche: suche100(q.suche), seite: seite4(q.seite) }) });
}
// Migrationen 47–50 (Stefan 18.10.2026): t3 = Daten der neuen Ansichten (Feld t3, $8 in "Seite laden"), je Ansicht genau eine Datenbank-Funktion.
// Nur geprüfte Werte (Zahlen nur als Ziffern, Seiten ab 1), sonst weggelassen; ohne neue Ansicht fehlt das Feld (Seite laden setzt '{}').
const t3 = { art: '' };
const seiteN = v => seite4(v) && Number(seite4(v)) >= 1 ? String(Number(seite4(v))) : '';
const ARTEN47 = ['monat', 'kampagne', 'vergleich', 'mediakit', 'wunsch'];
const art47 = v => ARTEN47.includes(sq(v)) ? sq(v) : '';
if (ansicht === 'talents' && WERKZEUG.includes(tp.b || '')) {
  const tid = tp.talent || '', f = tp.filter || {};
  if (tp.b === 'berichte') Object.assign(t3, { art: 'berichte', filter: ohneLeer({ seite: seiteN(q.seite), vseite: seiteN(q.vseite), art: art47(q.art), talent: tid, neu: art47(q.neu), vorlage: zahl9(q.vorlage), export: zahl9(q.export) }) });
  else if (tp.b === 'zahlen') Object.assign(t3, { art: 'zahlen', talent: tid, filter: ohneLeer({ seite: seiteN(q.seite) }) });
  else if (tp.b === 'konzept') Object.assign(t3, { art: 'konzept', talent: tid });
  else if (tp.b === 'wf') Object.assign(t3, { art: 'wf', talent: tid, filter: ohneLeer({ kanal: f.kanal, zeitraum: f.zeitraum, von: f.von, bis: f.bis }) });
  else if (tp.b === 'marken') Object.assign(t3, { art: 'marken', talent: tid, filter: ohneLeer({ talent_id: tid, lauf_id: zahl9(q.lauf) }) });
  else if (tp.b === 'mails') Object.assign(t3, { art: 'mails', talent: tid, seite: seiteN(q.seite) || '1' });
  else if (tp.b === 'texte') Object.assign(t3, { art: 'texte', filter: ohneLeer({ talent_id: tid, text_id: zahl9(q.text), seite: seiteN(q.seite) }) });
  else if (tp.b === 'anfrage') Object.assign(t3, { art: 'anfrage', filter: ohneLeer({ anfrage_id: zahl9(q.anfrage), seite: seiteN(q.seite) }) });
}
// Einstellungen › Talents › KI-Funktionen bzw. Speicherort; Einstellungen › Superadmin › Plattform-Apps bzw. Meta (sa=plattformen|meta)
if (ansicht === 'einstellungen' && bereich === 'talents' && !tl.talent && ['ki', 'ablage'].includes(tl.tm)) t3.art = tl.tm;
if (ansicht === 'einstellungen' && bereich === 'superadmin' && ['plattformen', 'meta'].includes(sq(q.sa))) t3.art = sq(q.sa);
return [{ json: { token: /^[0-9a-f]{64}$/.test(roh) ? roh : '', meldung: String(q.m || '').replace(/[^a-z]/g, '').slice(0, 20), ansicht, bereich, code, offen, ordner, p: JSON.stringify(p), tl: JSON.stringify(tl), tp: JSON.stringify(tp), ...(t2.art ? { t2: JSON.stringify(t2) } : {}), ...(t3.art ? { t3: JSON.stringify(t3) } : {}) } }];

// Plan 51 / Migration 189 (Koordinator 31.10.2026): Buchungen ohne Preis zeigen „Kosten unbekannt“ statt 0 €; Summen mit einem unbekannten Teil zeigen den
// bekannten Betrag mit dem Zusatz „dazu N Aufrufe ohne Preis (Kosten unbekannt)“. ohne_preis/aufrufe kommen aus der Datenbank (Migration 189).
const KU_n = x => Math.max(0, Number((x || {}).ohne_preis) || 0);
const KU_alle = x => KU_n(x) > 0 && KU_n(x) >= (Number((x || {}).aufrufe) || 0);
const KU_t = n => n.toLocaleString('de-DE') + (n === 1 ? ' Aufruf' : ' Aufrufe') + ' ohne Preis';
const KU_dazu = n => 'dazu ' + KU_t(n) + ' (Kosten unbekannt)';
const KU_wert = (x, betrag) => KU_alle(x) ? 'Kosten unbekannt (' + KU_t(KU_n(x)) + ')' : KU_n(x) ? betrag + ' · ' + KU_dazu(KU_n(x)) : betrag;
// Seite bauen: Anmeldung, Passwort festlegen, Übersicht oder Monatsbericht – eine Oberfläche, Inhalte je nach Rechten
const CD = $('Corporate Design (CD 1)').first().json;
const A = $('Anfrage lesen').first().json;
const S = $('Seite laden').first().json.s || { angemeldet: false };
const SEITE = '/webhook/web';
const AKTION = '/webhook/web/aktion';

const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
// Produktname aus der Datenbank (produkt_name() im Knoten "Seite laden"), kein fester Name im Code; PNE = HTML-escapt (Stefan 18.10.2026)
const PN = String($('Seite laden').first().json.produkt_name || '').trim(), PNE = esc(PN);
const mitName = t => (PN ? PN + ' – ' : '') + t; // Seitentitel: "<Produktname> – <Titel>" (Stefan 18.10.2026)
const F = CD.farben, AB = CD.abgeleitet;
const stil = `${CD.fontCss}
:root { --dunkel:${F.dunkel}; --weiss:${F.textAufDunkel}; --akzent:${F.akzent}; --akzentDunkel:${F.akzentDunkel}; --hell:${F.hell}; --grau:${F.grau}; --warn:${F.warnung}; --linie:${AB.tabellenLinie}; --neben:${AB.dunkelNebentext}; }
