const leiste = wer => '<header class="leiste"><div class="innen"><a href="' + SEITE + '" aria-label="Zur Startseite"><img src="' + esc(CD.logos.logo_fuer_dunkel) + '" alt="' + PNE + '"></a>' + (wer || '') + '</div></header>';
