const huelle = (inhalt, titel) => `<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex, nofollow"><title>${esc(titel || PN)}</title><style>${stil}</style></head><body>${inhalt}${skript}</body></html>`;

// Passwörter verlassen den Browser nie im Klartext: es wird nur SHA-256('ally-v2:' + Passwort) geschickt (Startcode: 'ally-code:' + Code).
// Bei der Anmeldung zusätzlich die Prüfsumme nach altem Verfahren (mit Benutzername), damit bisherige Passwörter umgestellt werden können.
const skript = `<script>
async function sha(t) { const b = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(t)); return Array.from(new Uint8Array(b)).map(x => x.toString(16).padStart(2, '0')).join(''); }
document.querySelectorAll('form[data-pw]').forEach(f => f.addEventListener('submit', async e => {
  if (f.dataset.fertig) return;
  e.preventDefault();
  const fehler = f.querySelector('.fehlertext');
  const art = f.dataset.pw;
  const wert = n => (f.querySelector('[data-feld=' + n + ']') || {}).value || '';
  const setze = (n, v) => { f.querySelector('input[type=hidden][name=' + n + ']').value = v; };
  const v2 = p => sha('ally-v2:' + p);
  if (art === 'login') {
    const u = ((f.querySelector('[name=benutzer]') || {}).value || '').trim().toLowerCase();
    const p = wert('pw');
    setze('h', await v2(p));
    setze('ha', await sha('ally:' + u + ':' + p));
    setze('hc', await sha('ally-code:' + p.toUpperCase().replace(/[^A-Z0-9]/g, '')));
  } else if (art === 'profil') {
    // Bisheriges Passwort nur nötig, wenn sich E-Mail-Adresse oder Passwort ändern
    const alt = wert('alt'), neu = wert('neu'), wdh = wert('wiederholung');
    const mail = ((f.querySelector('[name=email]') || {}).value || '').trim().toLowerCase();
    if (!/^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$/.test(mail)) { fehler.textContent = 'Bitte eine gültige E-Mail-Adresse angeben.'; return; }
    if (neu || wdh) {
      if (neu.length < 10) { fehler.textContent = 'Das neue Passwort muss mindestens 10 Zeichen lang sein.'; return; }
      if (neu !== wdh) { fehler.textContent = 'Die beiden neuen Passwörter stimmen nicht überein.'; return; }
    }
    if ((neu || mail !== (f.dataset.mail || '')) && !alt) { fehler.textContent = 'Zum Ändern von E-Mail-Adresse oder Passwort bitte dein bisheriges Passwort eingeben.'; return; }
    setze('alt', alt ? await v2(alt) : '');
    setze('neu', neu ? await v2(neu) : '');
    setze('wiederholung', wdh ? await v2(wdh) : '');
    setze('laenge', String(neu.length));
  } else {
    const neu = wert('neu'), wdh = wert('wiederholung');
    if (neu.length < 10) { fehler.textContent = 'Das neue Passwort muss mindestens 10 Zeichen lang sein.'; return; }
    if (neu !== wdh) { fehler.textContent = 'Die beiden neuen Passwörter stimmen nicht überein.'; return; }
    setze('neu', await v2(neu));
    setze('wiederholung', await v2(wdh));
    setze('laenge', String(neu.length));
  }
  f.querySelectorAll('input[type=password]').forEach(i => { i.value = ''; });
  f.dataset.fertig = '1';
  f.submit();
}));
document.querySelectorAll('form[data-signatur]').forEach(f => f.addEventListener('submit', () => {
  f.querySelector('input[name=signatur_html]').value = f.querySelector('.editor').innerHTML;
}));
// Rückfrage ohne Browser-Dialog (die Sandbox von n8n kann Dialoge blockieren): erster Klick fragt, zweiter Klick bestätigt
document.querySelectorAll('form[data-frage]').forEach(f => f.addEventListener('submit', e => {
  if (f.dataset.ok === '1') return;
  e.preventDefault();
  const k = e.submitter || f.querySelector('button');
  let r = f.querySelector('.rueckfrage');
  if (!r) { r = document.createElement('div'); r.className = 'rueckfrage'; f.appendChild(r); }
  r.textContent = f.dataset.frage + ' Zum Bestätigen noch einmal klicken.';
  f.dataset.ok = '1';
  if (k) { k.dataset.text = k.textContent; k.textContent = 'Ja, bestätigen'; }
  setTimeout(() => { f.dataset.ok = ''; r.remove(); if (k && k.dataset.text) k.textContent = k.dataset.text; }, 10000);
}));
// Einstellungen: Höhe des feststehenden Seitenkopfs messen, damit die Themen direkt darunter stehen bleiben
(() => { const k = document.querySelector('.einst-seite .seitenkopf'); if (!k) return; const setz = () => document.documentElement.style.setProperty('--kopf', k.offsetHeight + 'px'); setz(); addEventListener('resize', setz); if (document.fonts) document.fonts.ready.then(setz); })();
// Handy: aktives Thema in der Themenleiste sichtbar machen
(() => { const t = document.querySelector('.themen'), a = t && t.querySelector('.aktiv'); if (t && a && t.scrollWidth > t.clientWidth) t.scrollLeft = a.offsetLeft - t.offsetLeft - 16; })();
</script>`;

const hinweisBox = (text, art) => text ? '<div class="hinweis ' + (art === 'fehler' ? 'fehler' : 'ok') + '">' + esc(text) + '</div>' : '';
let html, cookieLoeschen = false;

if (!S.angemeldet) {
