        '<form class="karte login" method="POST" action="' + AKTION + '" data-pw="setzen"><input type="hidden" name="aktion" value="passwort_neu"><input type="hidden" name="code" value="' + esc(A.code) + '">' +
        '<input type="hidden" name="neu"><input type="hidden" name="wiederholung"><input type="hidden" name="laenge">' + meldBox +
        '<input type="email" value="' + esc(C.email) + '" autocomplete="username" readonly hidden>' +
        '<label class="feld">Neues Passwort (mindestens 10 Zeichen)</label><input type="password" data-feld="neu" autocomplete="new-password" required>' +
        '<label class="feld">Neues Passwort wiederholen</label><input type="password" data-feld="wiederholung" autocomplete="new-password" required>' +
        '<div class="fehlertext"></div><button class="voll" type="submit">Passwort speichern</button></form>'
      : seitenkopf('', 'Neues Passwort') + '<section class="karte login">' + hinweisBox('Der Link ist abgelaufen oder wurde schon benutzt. Ein Link gilt eine Stunde und nur einmal.', 'fehler') +
        '<a class="knopf voll" style="text-align:center" href="' + adresse('vergessen') + '">Neuen Link anfordern</a>' + zurAnmeldung + '</section>') +
      '</main>', mitName('Neues Passwort'));
  } else {
    html = huelle(leiste('') + '<main class="rahmen schmal">' + seitenkopf('', 'Anmeldung') +
      '<form class="karte login" method="POST" action="' + AKTION + '" data-pw="login" autocomplete="on">' +
      '<input type="hidden" name="aktion" value="login"><input type="hidden" name="h" value=""><input type="hidden" name="ha" value=""><input type="hidden" name="hc" value="">' + meldBox +
      '<label class="feld" for="benutzer">E-Mail-Adresse</label><input type="text" id="benutzer" name="benutzer" inputmode="email" autocomplete="username" autocapitalize="none" spellcheck="false" required>' +
      '<label class="feld" for="pw">Passwort oder Startcode</label><input type="password" id="pw" data-feld="pw" autocomplete="current-password" required>' +
      '<div class="fehlertext"></div><button class="voll" type="submit">Anmelden</button>' +
      '<p class="klein" style="margin-top:14px"><a href="' + adresse('vergessen') + '">Passwort vergessen?</a></p></form></main>', mitName('Anmeldung'));
  }
} else if (S.muss_pw_setzen) {
  const n = S.nutzer;
  html = huelle(leiste('') + '<main class="rahmen schmal">' + seitenkopf('', 'Passwort festlegen', 'Hallo ' + n.name + ', bitte lege jetzt dein eigenes Passwort fest.') +
    hinweisBox(S.hinweis, S.hinweis_art) +
    '<form class="karte login" method="POST" action="' + AKTION + '" data-pw="setzen">' +
    '<input type="hidden" name="aktion" value="passwort_setzen"><input type="hidden" name="neu"><input type="hidden" name="wiederholung"><input type="hidden" name="laenge">' +
    '<label class="feld">Neues Passwort (mindestens 10 Zeichen)</label><input type="password" data-feld="neu" autocomplete="new-password" required>' +
    '<label class="feld">Neues Passwort wiederholen</label><input type="password" data-feld="wiederholung" autocomplete="new-password" required>' +
    '<div class="fehlertext"></div><button class="voll" type="submit">Passwort speichern</button></form></main>', mitName('Passwort festlegen'));
} else {
  const n = S.nutzer, D = S.daten || {}, R = n.rechte || [];
  const darf = r => R.includes(r);
  const admin = darf('admin');
  const E = D.einstellungen || {};
  const sw = (name, an, label) => '<label class="schalter"><input type="checkbox" name="' + esc(name) + '" value="1"' + (an ? ' checked' : '') + ' aria-label="' + esc(label) + '"><span></span></label>';
  const form = (aktion, inner, extra) => '<form method="POST" action="' + AKTION + '"' + (extra || '') + '><input type="hidden" name="aktion" value="' + aktion + '">' + inner + '</form>';
  const frage = t => ' data-frage="' + esc(t) + '"';
  const TAGE = ['Montag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag', 'Samstag', 'Sonntag'];
  const KAT = { keine: 'Bleibt im Posteingang', geschaeft: 'Geschäftlich (Steuern, Finanzen, Behörden)', kunde: 'Kunde', spam: 'Spam', system_report: 'System-Report' };
  const RECHTE = D.rechte_liste || [];
  const rechtName = k => (RECHTE.find(r => r.schluessel === k) || {}).name || k;
  const mb = A.ansicht === 'monatsbericht' && darf('monatsbericht');
  const wer = '<div class="wer"><span>' + esc(n.name) + (admin ? ' · Admin' : '') + '</span>' + form('abmelden', '<button type="submit">Abmelden</button>') + '</div>';
  const zurStart = '<a href="' + SEITE + '">Start</a>';
  const hinweis = hinweisBox(S.hinweis, S.hinweis_art);
  const einst = A.ansicht === 'einstellungen';
  const KI = D.ki || null;
  const kiSicht = A.ansicht === 'verbrauch' && admin && KI;
  const zahl = (v, st) => Number(v || 0).toLocaleString('de-DE', { minimumFractionDigits: st, maximumFractionDigits: st });
  // Teil C (Stefan 19.10.2026): neutrale Namen der Stufen (Schwellen sind einstellbar, warn_prozent / spar_prozent)
  const STUFE = { ok: ['im Rahmen', 'an'], hinweis: ['Warnschwelle erreicht', ''], sparen: ['Sparmodus aktiv', 'aus'], gesperrt: ['Budget aufgebraucht, KI gesperrt', 'aus'], ueber_budget: ['Budget überschritten, wird nachberechnet', 'aus'] };

  if (mb) {
    // Monatsbericht: Projekte aus Papierkram (über PK 2), nur in dieser Ansicht abgerufen
    const pkLauf = $('Projekte laden (PK 2)').isExecuted ? ($('Projekte laden (PK 2)').first() || {}).json || {} : {};
    const pkFehler = !$('Projekte laden (PK 2)').isExecuted || pkLauf.error || !Array.isArray(pkLauf.eintraege);
    const projekte = pkFehler ? [] : pkLauf.eintraege;
    const kunden = {};
    if ($('Kunden laden').isExecuted) for (const k of $('Kunden laden').all()) if (k.json && k.json.papierkram_id) kunden[String(k.json.papierkram_id)] = String(k.json.name || '').trim();
    const euro = v => Number(v).toLocaleString('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' €';
    const datum = d => d ? String(d).slice(0, 10).split('-').reverse().join('.') : '';
    const MON = ['Januar', 'Februar', 'März', 'April', 'Mai', 'Juni', 'Juli', 'August', 'September', 'Oktober', 'November', 'Dezember'];
    const heute = DateTime.now().setZone('Europe/Berlin').startOf('month');
    const tag = d => DateTime.fromISO(String(d).slice(0, 10), { zone: 'Europe/Berlin' });
    // Monatsauswahl nur bei Projekten über mehrere Monate oder ohne festen Zeitraum (neuester Monat zuerst)
    const monate = p => {
      const st = p.start_date ? tag(p.start_date) : null, en = p.end_date ? tag(p.end_date) : null;
      if (st && en && st.hasSame(en, 'month')) return [];
      const a = (st || tag(p.created_at)).startOf('month');
      let b = en ? en.startOf('month') : heute;
      if (b > heute) b = heute;
      const out = [];
      for (let m = b; m >= a && out.length < 36; m = m.minus({ months: 1 })) out.push({ w: m.toFormat('yyyy-LL'), t: MON[m.month - 1] + ' ' + m.year });
      if (!out.length) out.push({ w: a.toFormat('yyyy-LL'), t: MON[a.month - 1] + ' ' + a.year });
      return out;
    };
    const vormonat = heute.minus({ months: 1 }).toFormat('yyyy-LL');
