    // Personen und Rechte (nur Admin)
    const personen = D.personen || [];
    const marke = p => !p.ally_aktiv ? '<span class="marke aus">deaktiviert</span>' : (!p.hat_zugang ? '<span class="marke">kein Zugang</span>' :
