        esc(p.ally_aktiv ? ((p.rechte || []).includes('admin') ? 'Admin' : ((p.rechte || []).length ? (p.rechte || []).map(rechtName).join(', ') : 'keine besonderen Rechte')) : 'deaktiviert') + '</span></div>' + marke(p) + '</summary>' +
        '<p class="klein" style="margin-top:10px">' + (p.email ? 'E-Mail: ' + esc(p.email) + ' · ' : 'Keine E-Mail-Adresse · ') + 'Chat-Adresse: ' + esc(p.id) + (p.letzte_anmeldung ? ' · Letzte Anmeldung: ' + esc(p.letzte_anmeldung) : '') + '</p>' +
        (!p.ally_aktiv
          ? form('person_ally', '<input type="hidden" name="id" value="' + esc(p.id) + '"><input type="hidden" name="aktiv" value="1"><button class="zweit" type="submit">Wieder aktivieren</button>')
          : form('person_rechte', '<input type="hidden" name="id" value="' + esc(p.id) + '"><label class="feld">Rechte</label>' +
              // B6 (Migration 167, F13): hier nur noch Admin und (für Superadmins) Superadmin; alle übrigen Rechte stehen in der Rolle oder unter „Eigene Rechte“
              // (Einstellungen › Team und Rollen). Prüfung M167 M1: Mit dem Häkchen „Superadmin“ geht die Kennung recht__superadmin_feld mit; nur dann wertet die
              // Datenbank ein fehlendes Häkchen als Wegnahme. Migration 168 (Bauplan B7, G1): Häkchen „Superadmin“ nur für Personen aus der Liste superadmin_personen.
              RECHTE.filter(r => ['admin', 'superadmin'].includes(r.schluessel)).map(r => (r.schluessel === 'superadmin' ? '<input type="hidden" name="recht__superadmin_feld" value="1">' : '') +
                '<label class="wahl" style="margin:8px 0"><input type="checkbox" name="recht__' + esc(r.schluessel) + '" value="1"' + ((p.rechte || []).includes(r.schluessel) ? ' checked' : '') +
                (p.id === n.id && r.schluessel === 'admin' ? ' disabled' : '') + (r.schluessel === 'superadmin' && p.superadmin_moeglich === false ? ' disabled' : '') + '><span>' + esc(r.name) + '<span class="unter2">' + esc(r.beschreibung) + '</span></span></label>' +
                (p.id === n.id && r.schluessel === 'admin' ? '<input type="hidden" name="recht__admin" value="1">' : '')).join('') +
              '<button type="submit">Rechte speichern</button>') +
            form('person_daten', '<input type="hidden" name="id" value="' + esc(p.id) + '"><div class="zwei"><div><label class="feld">Name</label><input type="text" name="name" value="' + esc(p.name) + '" required></div>' +
              '<div><label class="feld">E-Mail-Adresse (für die Anmeldung)</label><input type="email" name="email" value="' + esc(p.email || '') + '" autocapitalize="none"></div></div>' +
              '<button class="zweit" type="submit">Name und E-Mail speichern</button>') +
            (p.email ? form('person_zugang', '<input type="hidden" name="id" value="' + esc(p.id) + '">' +
              '<button class="zweit" type="submit" style="margin-top:16px">' + (p.hat_zugang ? 'Neuen Startcode erzeugen' : 'Zugang anlegen (Startcode)') + '</button>',
              p.hat_zugang ? frage('Neuen Startcode erzeugen? ' + (p.id === n.id ? 'Dein Passwort bleibt gültig.' : 'Das bisherige Passwort wird ungültig.')) : '')
              : '<p class="klein" style="margin-top:16px">' + (p.hat_zugang ? 'Bitte eine E-Mail-Adresse eintragen. Damit meldet sich die Person künftig an.' : 'Für einen Zugang zur Oberfläche bitte zuerst eine E-Mail-Adresse eintragen.') + '</p>') +
            (p.id === n.id ? '' : '<div class="knopfreihe">' +
              (p.hat_zugang ? form(p.zugang_aktiv ? 'person_sperren' : 'person_freigeben', '<input type="hidden" name="id" value="' + esc(p.id) + '"><button class="klein ' + (p.zugang_aktiv ? 'gefahr' : 'zweit') + '" type="submit">' + (p.zugang_aktiv ? 'Zugang zur Oberfläche sperren' : 'Zugang freigeben') + '</button>') : '') +
              form('person_ally', '<input type="hidden" name="id" value="' + esc(p.id) + '"><input type="hidden" name="aktiv" value="0"><button class="klein gefahr" type="submit">Person deaktivieren</button>', frage(p.name + ' deaktivieren? Danach kein Chat mit ' + PN + ' und keine Anmeldung mehr.')) + '</div>')) +
        '</details>').join('') +
      form('person_neu', '<h3 style="margin-top:20px">Neue Person</h3><div class="zwei"><div><label class="feld">Chat-Adresse</label><input type="text" name="id" placeholder="@vorname:chat.firma.de" required autocapitalize="none"></div>' +
        '<div><label class="feld">Name</label><input type="text" name="name" required></div></div>' +
        '<label class="feld">E-Mail-Adresse (für die Anmeldung)</label><input type="email" name="email" autocapitalize="none"><button type="submit">Person anlegen</button>') +
      '<details class="ui-technik"><summary>Technische Angaben</summary><div class="ui-technik-inhalt"><p>Ein Admin hat automatisch alle Rechte. Mit einem Startcode meldet sich die Person mit ihrer E-Mail-Adresse an und legt dann ihr eigenes Passwort fest; ' +
      'ein Startcode gilt 7 Tage und wird nur einmal angezeigt. Für eine neue Person muss das Chat-Konto auf dem Chat-Server schon angelegt sein.</p></div></details></section>';

    // Mein Profil: Name, E-Mail-Adresse (Anmeldung), Passwort; Chat-Adresse nur zur Info
    const profil = '<section class="karte" id="profil"><h2>Mein Profil</h2><p class="unter">Name, Anmeldung mit E-Mail-Adresse und Passwort.</p>' +
      '<form method="POST" action="' + AKTION + '" data-pw="profil" data-mail="' + esc(n.email || '') + '"><input type="hidden" name="aktion" value="profil"><input type="hidden" name="alt"><input type="hidden" name="neu"><input type="hidden" name="wiederholung"><input type="hidden" name="laenge">' +
      '<div class="zwei"><div><label class="feld" for="p_name">Name</label><input type="text" id="p_name" name="name" value="' + esc(n.name || '') + '" autocomplete="name" required></div>' +
      '<div><label class="feld" for="p_mail">E-Mail-Adresse</label><input type="email" id="p_mail" name="email" value="' + esc(n.email || '') + '" autocomplete="username" autocapitalize="none" spellcheck="false" required></div></div>' +
      '<label class="feld">Chat-Adresse</label><input type="text" value="' + esc(n.id) + '" readonly disabled><div class="klein">Ändert ein Admin</div>' +
      '<label class="feld">Bisheriges Passwort</label><input type="password" data-feld="alt" autocomplete="current-password"><div class="klein">Nur nötig beim Ändern von E-Mail-Adresse oder Passwort</div>' +
      '<div class="zwei"><div><label class="feld">Neues Passwort (mind. 10 Zeichen)</label><input type="password" data-feld="neu" autocomplete="new-password"></div>' +
      '<div><label class="feld">Wiederholen</label><input type="password" data-feld="wiederholung" autocomplete="new-password"></div></div><div class="klein">Leer lassen = Passwort bleibt gleich</div>' +
      '<div class="fehlertext"></div><button type="submit">Profil speichern</button></form></section>';

    // Einstellungen: links (Handy: oben) die Themen, rechts immer nur das gewählte Thema
    const THEMEN = [['funktionen', PN + '-Funktionen', funktionen], ['meine', 'Meine Einstellungen', einstellungen], ['postfaecher', 'Postfächer', postfaecher], ['regeln', 'Absender-Regeln', regeln]]
      .concat(darf('instagram') ? [['instagram', 'Instagram-Zugang', instagram]] : [])
      .concat(admin ? [['personen', 'Personen und Rechte', personenKarte]] : [])
      .concat([['profil', 'Mein Profil', profil]]);
    const akt = THEMEN.find(t => t[0] === A.bereich) || THEMEN[0];
    const themen = '<nav class="themen" aria-label="Einstellungen">' + THEMEN.map(t => '<a href="' + adresse('einstellungen', t[0]) + '"' + (t === akt ? ' class="aktiv" aria-current="page"' : '') + '>' + esc(t[1]) + '</a>').join('') + '</nav>';
    html = huelle(leiste(wer) + '<main class="rahmen einst-seite">' + seitenkopf(zurStart + ' › Einstellungen', 'Einstellungen') +
      '<div class="einst">' + themen + '<div>' + hinweis + akt[2] + '</div></div></main>', mitName('Einstellungen – ') + akt[1]);
  }
}

const cookie = cookieLoeschen ? 'ally_sitzung=; Path=' + SEITE + '; Max-Age=0; HttpOnly; Secure; SameSite=None' : '';
return [{ json: { html, set_cookie: cookie } }];

// Formular lesen: Herkunft prüfen (Schutz gegen fremde Seiten), Sitzung aus dem Cookie, Felder je Aktion aufbereiten
// Eigene Adresse aus der Anfrage (Host-Kopfzeile, von traefik unverändert weitergegeben). n8n ist nur über traefik erreichbar,
// traefik leitet nur eingerichtete Adressen weiter. So gelten die bisherige n8n-Adresse und die eigene Adresse der Oberfläche ohne feste Werte (17.10.2026).
const HOST = (x => /^[a-z0-9.-]{1,253}$/.test(x) ? 'https://' + x : '')(String(($json.headers || {}).host || '').trim().toLowerCase());
const h = $json.headers || {};
const b = $json.body || {};
const herkunft = String(h.origin || '');
const verweis = String(h.referer || '');
// n8n liefert die Seite mit CSP-Sandbox aus (ohne allow-same-origin); der Browser meldet dann Origin "null".
// Deshalb: echte Herkunft = unser Host, oder Origin leer/null UND Verweis von genau dieser Seite.
// Verweis muss genau diese Seite sein (danach Ende, /, ? oder #), nicht z. B. /webhook/web-fremd (Stefan 17.10.2026)
const SEITE_PFAD = HOST + '/webhook/web';
const vonSeite = verweis.startsWith(SEITE_PFAD) && (verweis.length === SEITE_PFAD.length || '/?#'.includes(verweis[SEITE_PFAD.length]));
const herkunftOk = HOST !== '' && (herkunft === HOST || ((herkunft === '' || herkunft === 'null') && vonSeite));
const kekse = String(h.cookie || '').split(';').map(x => x.trim());
const roh = (kekse.find(x => x.startsWith('ally_sitzung=')) || '').slice('ally_sitzung='.length);
const token = /^[0-9a-f]{64}$/.test(roh) ? roh : '';
const s = v => String(v ?? '').trim();
const aktion = herkunftOk ? s(b.aktion) : 'ungueltig';

// Signatur säubern: keine Skripte, keine Ereignis-Attribute, keine javascript:-Links, keine eingebetteten Fremdinhalte
const sauber = html => String(html || '')
  .replace(/<\s*(script|style|iframe|object|embed|form|input|button|textarea|select|meta|link|base)\b[\s\S]*?(<\/\s*\1\s*>|\/?>)/gi, '')
  .replace(/\son[a-z]+\s*=\s*("[^"]*"|'[^']*'|[^\s>]+)/gi, '')
  .replace(/(href|src)\s*=\s*(["'])\s*(javascript|vbscript|data:text)[^"']*\2/gi, '$1=$2#$2')
  .trim();
// Textversion der Signatur für Mailprogramme ohne HTML
const alsText = html => String(html || '')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/(div|p|li|tr|h[1-6])\s*>/gi, '\n')
  .replace(/<img[^>]*alt\s*=\s*["']([^"']*)["'][^>]*>/gi, '')
  .replace(/<[^>]+>/g, '')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
  .split('\n').map(z => z.replace(/\s+$/, '')).join('\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

let daten = {};
if (aktion === 'funktionen') {
  for (const [k, v] of Object.entries(b)) if (/^(sichtbar|an)__[a-z0-9_]+$/.test(k)) daten[k] = '1';
} else if (aktion === 'einstellungen') {
  // Marketing-Felder nur, wenn das Formular sie mitschickt (sie stehen jetzt auf der Seite "Marketing")
  for (const k of ['briefing_uhrzeit', 'kalender_id', 'standard_postfach', 'marketing_tag', 'marketing_uhrzeit', 'marketing_profil', 'absender_name', 'signatur_name'])
    if (!k.startsWith('marketing_') || k in b) daten[k] = s(b[k]);
} else if (aktion === 'paket_fuer_mich') {
  // Seite eines Pakets, Teil "Für mich": Schalter der Funktionen und persönliche Werte, nur die mitgeschickten Felder
  daten = { paket: /^[a-z_]{1,30}$/.test(s(b.paket)) ? s(b.paket) : '' };
  for (const k of Object.keys(b)) if (/^(sichtbar|an)__[a-z0-9_]+$/.test(k)) daten[k] = '1';
  for (const k of ['briefing_uhrzeit', 'kalender_id', 'standard_postfach', 'absender_name', 'signatur_name', 'marketing_tag', 'marketing_uhrzeit', 'marketing_profil',
      'marketing_anzahl', 'marketing_ansprache', 'marketing_themenfelder', 'marketing_zielgruppe', 'marketing_stil', 'marketing_nogos'])
    if (k in b) daten[k] = s(b[k]);
} else if (aktion === 'ki_hinweis') {
  // KI-Hinweis "Erstellt mit KI-Unterstützung." für Mail-Entwürfe oder Marketing (für alle, nur Admins; prüft die Datenbank)
  daten = { art: ['mail', 'marketing'].includes(s(b.art)) ? s(b.art) : '' };
  if (b.an) daten.an = '1';
} else if (aktion === 'marketing') {
  for (const k of ['marketing_tag', 'marketing_uhrzeit', 'marketing_profil']) daten[k] = s(b[k]);
} else if (aktion === 'startseite') {
  // Reihenfolge der Kacheln; ein Pfeil verschiebt eine Kachel um eine Stelle, Schalter aus = ausgeblendet
  const reihe = s(b.reihenfolge).split(',').map(x => x.trim()).filter(x => /^[a-z_]{1,30}$/.test(x)).slice(0, 20);
  const [kWer, kWohin] = s(b.schieben).split(':');
  const ki = reihe.indexOf(kWer);
  if (ki > 0 && kWohin === 'hoch') [reihe[ki - 1], reihe[ki]] = [reihe[ki], reihe[ki - 1]];
  if (ki >= 0 && ki < reihe.length - 1 && kWohin === 'runter') [reihe[ki + 1], reihe[ki]] = [reihe[ki], reihe[ki + 1]];
  daten = { reihenfolge: reihe, aus: reihe.filter(k => k !== 'einstellungen' && !b['zeige__' + k]) };
} else if (aktion === 'postfach') {
  const sig = sauber(b.signatur_html);
  daten = { adresse: s(b.adresse), name: s(b.name), entwurf_ordner: s(b.entwurf_ordner), schrift: s(b.schrift), schrift_groesse: s(b.schrift_groesse), signatur_html: sig, signatur_text: alsText(sig),
    personen: Object.keys(b).filter(k => k.startsWith('person__')).map(k => k.slice('person__'.length)) };
  if (b.aktiv) daten.aktiv = '1';
  if (b.belege_sichtbar) { daten.belege_sichtbar = '1'; if (b.belege) daten.belege = '1'; }
  if (b.unternehmen_sichtbar) { daten.unternehmen_sichtbar = '1'; daten.unternehmen_id = /^[0-9]{1,9}$/.test(s(b.unternehmen_id)) ? s(b.unternehmen_id) : ''; }
  // Entwurfsangebote je Postfach und Einordnung je Postfach (Stefan 17.10.2026); geprüft wird in der Datenbank
  if (b.angebot_sichtbar) { daten.angebot_sichtbar = '1'; daten.angebot = ['kunde', 'geschaeft', 'antwort'].filter(k => b['angebot__' + k]); }
  if (b.einordnung_sichtbar) {
    daten.einordnung_sichtbar = '1'; if (b.gemeinsam) daten.gemeinsam = '1';
    daten.einordnung = {};
    for (const k of ['kunde', 'geschaeft', 'spam', 'system_report']) if (('einordnung__' + k) in b) daten.einordnung[k] = s(b['einordnung__' + k]).slice(0, 300);
  }
} else if (aktion === 'unternehmen') {
  daten = { id: /^[0-9]{1,9}$/.test(s(b.id)) ? s(b.id) : '', name: s(b.name), inhaber: s(b.inhaber), ort: s(b.ort), website: s(b.website), leistungen: s(b.leistungen) };
} else if (aktion === 'unternehmen_loeschen') {
  daten = { id: /^[0-9]{1,9}$/.test(s(b.id)) ? s(b.id) : '' };
} else if (aktion === 'cd') {
  daten = { id: /^[0-9]{1,9}$/.test(s(b.id)) ? s(b.id) : '', schrift: s(b.schrift) };
  for (const k of ['farbe_dunkel', 'farbe_text_auf_dunkel', 'farbe_akzent', 'farbe_akzent_dunkel', 'farbe_hell', 'farbe_grau', 'farbe_warnung']) daten[k] = s(b[k]).toUpperCase();
} else if (aktion === 'cd_gestaltung') {
  daten = { id: /^[0-9]{1,9}$/.test(s(b.id)) ? s(b.id) : '', stile: ['dunkel', 'hell', 'akzent'].filter(k => b['stil__' + k]) };
  for (const k of ['punkte', 'boegen', 'gross_icon', 'icons']) if (b[k]) daten[k] = '1';
  if (b.icons_sichtbar) daten.icons_liste = Object.keys(b).filter(k => /^icon__[a-z0-9-]{1,40}$/.test(k)).map(k => k.slice('icon__'.length));
} else if (aktion === 'hintergrund_loeschen') {
  daten = { id: /^[0-9]{1,9}$/.test(s(b.id)) ? s(b.id) : '', bild: /^[0-9]{1,9}$/.test(s(b.bild)) ? s(b.bild) : '' };
} else if (aktion === 'cd_datei_loeschen') {
  daten = { id: /^[0-9]{1,9}$/.test(s(b.id)) ? s(b.id) : '', art: s(b.art) };
} else if (aktion === 'start') {
  // Startseite: eine Arbeit starten (Belege verbuchen, Abgleich, Themen, Beitrag, Kundenüberblick, Briefing); prüft die Datenbank (ally_web_start)
  const was = s(b.was);
  daten = { was: ['belege', 'abgleich', 'themen', 'beitrag', 'kundenueberblick', 'briefing'].includes(was) ? was : '',
    thema: /^[0-9]{1,9}$/.test(s(b.thema)) ? s(b.thema) : '', kunde: /^[0-9]{1,12}$/.test(s(b.kunde)) ? s(b.kunde) : '' };
} else if (aktion === 'regel_neu') {
  // postfach: leer oder "alle" = alle Postfächer, sonst nur dieses Postfach
  daten = { muster: s(b.muster), kategorie: s(b.kategorie), notiz: s(b.notiz), postfach: s(b.postfach).toLowerCase() };
} else if (aktion === 'regel_loeschen') {
  daten = { muster: s(b.muster), postfach: s(b.postfach).toLowerCase() };
} else if (['person_zugang', 'person_sperren', 'person_freigeben'].includes(aktion)) {
  daten = { id: s(b.id) };
} else if (aktion === 'person_neu' || aktion === 'person_daten') {
  daten = { id: aktion === 'person_neu' ? s(b.id).toLowerCase() : s(b.id), name: s(b.name), email: s(b.email).toLowerCase() };
} else if (aktion === 'person_ally') {
  daten = { id: s(b.id), aktiv: s(b.aktiv) === '1' ? '1' : '0' };
} else if (aktion === 'person_rechte') {
  daten = { id: s(b.id) };
  for (const k of Object.keys(b)) if (/^recht__[a-z_]+$/.test(k)) daten[k] = '1';
} else if (aktion === 'passwort_setzen') {
  daten = { neu: s(b.neu), wiederholung: s(b.wiederholung), laenge: s(b.laenge) };
} else if (aktion === 'profil') {
  daten = { name: s(b.name), email: s(b.email).toLowerCase(), alt: s(b.alt), neu: s(b.neu), wiederholung: s(b.wiederholung), laenge: s(b.laenge) };
} else if (aktion === 'passwort_vergessen') {
  daten = { email: s(b.email).toLowerCase() };
} else if (aktion === 'passwort_neu') {
  daten = { code: /^[0-9a-f]{64}$/.test(s(b.code)) ? s(b.code) : '', neu: s(b.neu), wiederholung: s(b.wiederholung), laenge: s(b.laenge) };
}

// KI und Superadmin (Stefan 18.10.2026): Formularname -> [Datenbank-Funktion, Aktion]. sa = superadmin_web_aktion, ki = ki_web_aktion,
// alles andere wie bisher ally_web_aktion. Zahlen gehen als Text, Schalter als '1'/'0'; prüfen und Meldung setzen tut die Datenbank.
const FN = { sa_vertrag: ['sa', 'vertrag'], sa_module: ['sa', 'module'], sa_ki: ['sa', 'ki'], sa_produkt: ['sa', 'produkt'], sa_person_admin: ['sa', 'person_admin'],
  sa_person_superadmin: ['sa', 'person_superadmin'], sa_modell_freigabe: ['sa', 'modell_freigabe'], ki_modelle: ['ki', 'ki_modelle'] }[aktion] || ['', ''];
if (aktion === 'sa_vertrag') daten = { paket: s(b.paket), ki_budget_eur: s(b.ki_budget_eur), budget_modus: s(b.budget_modus), warn_prozent: s(b.warn_prozent), spar_prozent: s(b.spar_prozent) };
else if (aktion === 'sa_module') daten = { module: Object.keys(b).filter(x => /^modul__[a-z0-9_]{1,40}$/.test(x)).map(x => x.slice('modul__'.length)) };
else if (aktion === 'sa_ki') daten = { ki_schluessel: s(b.ki_schluessel), preis_faktor: s(b.preis_faktor), eigener_schluessel_erlaubt: b.eigener_schluessel_erlaubt ? '1' : '0' };
else if (aktion === 'sa_produkt') daten = { produkt_name: s(b.produkt_name), anbieter_name: s(b.anbieter_name) };
else if (aktion === 'sa_person_admin') daten = { id: s(b.id), admin: b.admin ? '1' : '0' };
else if (aktion === 'sa_person_superadmin') daten = { id: s(b.id), superadmin: b.superadmin ? '1' : '0' };
else if (aktion === 'sa_modell_freigabe') daten = { modell: s(b.modell), freigegeben: b.freigegeben ? '1' : '0' };
else if (aktion === 'ki_modelle') daten = { einfach: s(b.einfach), anspruchsvoll: s(b.anspruchsvoll) };
// Talents (Stefan 18.10.2026): Formulare tl_<aktion> gehen an talents_web_aktion (fn 'tl'); Listen aus Kästchen person__<id> und kanal__<plattform>.
// Prüfen (Rechte, Werte) und Meldung setzen tut die Datenbank.
// Migration 46 (Stefan 18.10.2026): links_erneuern = Sammel-Aktion "Neue Links für abgelaufene Verbindungen und Einladungen" (ohne Daten)
const TL_AKTIONEN = ['talent_neu', 'talent_bearbeiten', 'einladung_neu', 'kanal_trennen', 'talent_archivieren', 'talent_reaktivieren', 'talent_loeschen', 'einstellungen', 'links_erneuern'];
if (/^tl_[a-z_]{1,40}$/.test(aktion) && TL_AKTIONEN.includes(aktion.slice(3))) {
  FN[0] = 'tl'; FN[1] = aktion.slice(3);
  const id = /^[0-9]{1,9}$/.test(s(b.id)) ? s(b.id) : '';
  const liste = pre => Object.keys(b).filter(x => x.startsWith(pre) && x.length > pre.length && x.length <= 300).map(x => x.slice(pre.length));
  if (FN[1] === 'talent_neu' || FN[1] === 'talent_bearbeiten') {
    daten = { name: s(b.name), kuenstlername: s(b.kuenstlername), email: s(b.email).toLowerCase(), notiz: s(b.notiz), personen: liste('person__'), kanaele: liste('kanal__') };
    if (FN[1] === 'talent_bearbeiten') { daten.id = id; if ('verfolgung_tage' in b) daten.verfolgung_tage = s(b.verfolgung_tage); }
    // Name ist optional (Stefan 18.10.2026): leer = nicht mitschicken, der gespeicherte Name bzw. der Account-Name bleibt
    if (FN[1] === 'talent_bearbeiten' && !daten.name) delete daten.name;
  // Trennen je Account (Stefan 18.10.2026), Migration 45: kanal_id (prüft die Datenbank); plattform nur als Rückfall, wenn genau ein Account dieser Plattform verbunden ist
  } else if (FN[1] === 'kanal_trennen') daten = { id, kanal_id: s(b.kanal_id).slice(0, 12), plattform: s(b.plattform) };
  else if (FN[1] === 'talent_loeschen') daten = { id, bestaetigung: s(b.bestaetigung) };
  // Standards der Agentur (Stefan 18.10.2026), Migration 46: jedes Formular schickt nur seine Felder (teil = einladungstext, loeschfrist, warnungen);
  // die Datenbank setzt nur übergebene Felder. Ohne teil wie bisher (Verfolgung und Gültigkeit der Einladungslinks).
  else if (FN[1] === 'einstellungen' && s(b.teil) === 'einladungstext') daten = { einladung_betreff: s(b.einladung_betreff), einladung_vorlage: String(b.einladung_vorlage ?? '').replace(/\r\n?/g, '\n').trim() };
  else if (FN[1] === 'einstellungen' && s(b.teil) === 'loeschfrist') daten = { loeschfrist_tage: s(b.loeschfrist_tage), loeschwarnung_tage: s(b.loeschwarnung_tage) };
  else if (FN[1] === 'einstellungen' && s(b.teil) === 'warnungen') daten = { kampagne_warnung_tage: s(b.kampagne_warnung_tage) };
  else if (FN[1] === 'einstellungen') daten = { verfolgung_tage: s(b.verfolgung_art) === 'unbegrenzt' ? 'unbegrenzt' : s(b.verfolgung_zahl), einladung_tage: s(b.einladung_tage) };
  else if (FN[1] === 'links_erneuern') daten = {};
  else daten = { id };
}

// Meta-App für die Instagram-Anmeldung (Stefan 18.10.2026), Migration 45: Formular sa_meta_ig geht an meta_ig_app_web_aktion (fn 'mi').
// Der App-Geheimcode kommt NICHT in "daten" (Ausgabe dieses Knotens); "Aktion ausführen" liest ihn direkt aus dem Webhook "Aktion" (wie das Meta-App-Formular in ALLY 16).
if (aktion === 'sa_meta_ig') { FN[0] = 'mi'; FN[1] = 'meta_ig'; daten = { app_id: s(b.app_id).slice(0, 40) }; }

// Talents-Seiten (Stefan 18.10.2026): Formular tb_verfolgung ("Verfolgung für diesen Beitrag") geht an talents_beitrag_verfolgung (fn 'tb').
// verfolgung = 'standard', 'unbegrenzt' oder die Tage (bei "Eigene Dauer in Tagen"); talent nur für den Rücksprung. Prüfen und Meldung setzen tut die Datenbank.
if (aktion === 'tb_verfolgung') {
  FN[0] = 'tb'; FN[1] = 'verfolgung';
  const art = s(b.verfolgung_art);
  daten = { beitrag: /^[0-9]{1,12}$/.test(s(b.beitrag)) ? s(b.beitrag) : '', talent: /^[0-9]{1,9}$/.test(s(b.talent)) ? s(b.talent) : '',
    verfolgung: art === 'tage' ? s(b.verfolgung_tage).slice(0, 10) : ['standard', 'unbegrenzt'].includes(art) ? art : '' };
}

// Stufe 2 (Stefan 18.10.2026), Migration 46: Notizen (tn_* -> talents_notiz_aktion, fn 'tn'), Kampagnen (tk_* -> talents_kampagne_aktion, fn 'tk'),
// Import einer Tabelle (ti_* -> talents_import_aktion, fn 'ti'). IDs nur als Ziffern, Texte ungekürzt bis knapp über der Grenze der Datenbank
// (sie meldet zu lange Texte selbst). zurueck = Stelle für "Antwort bauen" (Seite der Notizen bzw. der Kampagne), geht nicht an die Datenbank.
const id9 = v => /^[0-9]{1,9}$/.test(s(v)) ? s(v) : '';
const id12 = v => /^[0-9]{1,12}$/.test(s(v)) ? s(v) : '';
const seite4 = v => /^[0-9]{1,4}$/.test(s(v)) ? s(v) : '';
const langText = (v, max) => String(v ?? '').replace(/\r\n?/g, '\n').slice(0, max);
let zurueck = {};
const TN = { tn_neu: 'notiz_neu', tn_bearbeiten: 'notiz_bearbeiten', tn_loeschen: 'notiz_loeschen' }[aktion];
if (TN) {
  FN[0] = 'tn'; FN[1] = TN;
  daten = TN === 'notiz_neu' ? { talent_id: id9(b.talent_id), text: langText(b.text, 4001) }
    : TN === 'notiz_bearbeiten' ? { id: id12(b.id), text: langText(b.text, 4001) }
    : { id: id12(b.id), bestaetigt: s(b.bestaetigt) === 'ja' ? 'ja' : '' };
  zurueck = { talent: id9(b.talent_id || b.talent), notizen: s(b.zurueck) === 'notizen' ? '1' : '', seite: seite4(b.seite) };
}
const TK = { tk_kampagne_neu: 'kampagne_neu', tk_kampagne_bearbeiten: 'kampagne_bearbeiten', tk_kampagne_loeschen: 'kampagne_loeschen', tk_beitrag_bestaetigen: 'beitrag_bestaetigen',
  tk_beitrag_zuordnen: 'beitrag_zuordnen', tk_beitrag_entfernen: 'beitrag_entfernen', tk_vorschlaege_bestaetigen: 'vorschlaege_bestaetigen' }[aktion];
if (TK) {
  FN[0] = 'tk'; FN[1] = TK;
  if (TK === 'kampagne_neu' || TK === 'kampagne_bearbeiten') {
    // Talents als Kästchen talent__<id>; Erkennungsmerkmale als Text (die Datenbank trennt und prüft sie)
    daten = { marke: s(b.marke).slice(0, 200), name: s(b.name).slice(0, 200), von: s(b.von).slice(0, 20), bis: s(b.bis).slice(0, 20),
      talents: Object.keys(b).filter(x => /^talent__[0-9]{1,9}$/.test(x)).map(x => Number(x.slice('talent__'.length))),
      marken_konten: s(b.marken_konten).slice(0, 2000), hashtags: s(b.hashtags).slice(0, 2000), schlagwoerter: s(b.schlagwoerter).slice(0, 2000) };
    if (TK === 'kampagne_bearbeiten') daten.id = id9(b.id);
  } else if (TK === 'kampagne_loeschen') daten = { id: id9(b.id), bestaetigung: s(b.bestaetigung).slice(0, 300) };
  else if (TK === 'vorschlaege_bestaetigen') daten = { kampagne_id: id9(b.kampagne_id) };
  else daten = { kampagne_id: id9(b.kampagne_id), beitrag_id: id12(b.beitrag_id) };
  zurueck = { kampagne: id9(b.kampagne_id || b.id), zuordnen: s(b.zurueck) === 'zuordnen' ? '1' : '', talent: id9(b.talent), bereich: ['zeitraum', 'alle'].includes(s(b.bereich)) ? s(b.bereich) : '',
    seite: seite4(b.seite), vseite: seite4(b.vseite), bseite: seite4(b.bseite), neu: TK === 'kampagne_neu' ? '1' : '', bearbeiten: TK === 'kampagne_bearbeiten' ? '1' : '' };
}
const TI = { ti_import_pruefen: 'import_pruefen', ti_import_anlegen: 'import_anlegen', ti_import_verwerfen: 'import_verwerfen' }[aktion];
if (TI) {
  FN[0] = 'ti'; FN[1] = TI;
  if (TI === 'import_pruefen') {
    // Datei aus dem Formular (multipart, Feld "datei"), wie bei den Corporate-Design-Dateien (ALLY 10). UTF-8, sonst Windows-1252 (Excel "CSV (Trennzeichen-getrennt)").
    // Über 200 000 Zeichen nur angeschnitten weitergeben: die Datenbank erkennt die Überschreitung und meldet sie.
    let csv = '';
    const it = $input.first() || {}, bin = it.binary || {};
    const k = Object.keys(bin).find(x => x === 'datei') || Object.keys(bin).find(x => x.startsWith('datei'));
    if (k) {
      const puf = await this.helpers.getBinaryDataBuffer(0, k);
      const roh = puf.subarray(0, 800004);
      const u8 = roh.toString('utf8');
      if (Buffer.from(u8, 'utf8').equals(roh) || puf.length > 800004) csv = u8;
      else {
        const W1252 = { 128: 8364, 130: 8218, 131: 402, 132: 8222, 133: 8230, 134: 8224, 135: 8225, 136: 710, 137: 8240, 138: 352, 139: 8249, 140: 338, 142: 381, 145: 8216, 146: 8217, 147: 8220, 148: 8221, 149: 8226, 150: 8211, 151: 8212, 152: 732, 153: 8482, 154: 353, 155: 8250, 156: 339, 158: 382, 159: 376 };
        csv = Array.from(roh, x => String.fromCharCode(W1252[x] || x)).join('');
      }
    }
    daten = { csv: csv.length > 200000 ? csv.slice(0, 200001) : csv };
  } else daten = { import_id: id9(b.import_id) };
  zurueck = { import: id9(b.import_id) };
}

// Migrationen 48–50 (Stefan 18.10.2026): Plattform-Apps (sa_plattform_app -> plattform_app_web_aktion, fn 'pa') und Meta: Datenlöschung und Rechtstexte
// (sa_meta_rechte -> meta_rueckmeldungen_web_aktion, fn 'mr'). Geheimcodes (app_secret, ig_basis_secret) NICHT in "daten"; "Aktion ausführen" liest sie direkt aus dem Webhook.
if (aktion === 'sa_plattform_app') { FN[0] = 'pa'; FN[1] = 'plattform_app';
  daten = { plattform: /^[a-z]{1,20}$/.test(s(b.plattform)) ? s(b.plattform) : '', app_id: s(b.app_id).slice(0, 200), an: s(b.an) === 'ja' ? 'ja' : '' }; }
if (aktion === 'sa_meta_rechte') { FN[0] = 'mr'; FN[1] = 'meta_rechte';
  daten = { loeschfrist_tage: s(b.loeschfrist_tage).slice(0, 10), kontakt_email: s(b.kontakt_email).slice(0, 300), anschrift: langText(b.anschrift, 400).trim(),
    impressum_url: s(b.impressum_url).slice(0, 600), freigeben: ['ja', 'nein'].includes(s(b.freigeben)) ? s(b.freigeben) : '' }; }
// Migration 49 (Stefan 18.10.2026): KI-Funktionen der Talents. kz_ Gesamtkonzept (talents_konzept_aktion), wf_ Was funktioniert (talents_wf_aktion), tx_ Texte (talents_texte_aktion),
// ma_ Markenanfrage (talents_anfrage_aktion), ms_ Marken-Suche (talents_markensuche_aktion), me_ Mail-Entwurf (talents_mail_entwurf_anlegen), kf_ KI-Funktionen (Admin),
// ab_ Speicherort der Talents-Dateien. Zahlen als Text, Listen als Array; prüfen, Rechte und Meldungstexte macht die Datenbank. z_* = Rücksprung (geht nicht an die Datenbank).
const KI_FN = { kz: ['angaben_speichern', 'erstellen', 'ueberarbeitung_anfordern', 'entwurf_speichern', 'aktivieren', 'verwerfen', 'ziel_speichern', 'ziel_loeschen'], wf: ['erstellen'],
  tx: ['erstellen', 'speichern', 'loeschen'], ma: ['starten'], ms: ['kriterium_hinzufuegen', 'kriterium_entfernen', 'suche_starten', 'bewerten', 'bewertung_zuruecknehmen'], me: ['anlegen'],
  kf: ['speichern'], ab: ['waehlen', 'dienst_speichern', 'dienst_entfernen', 'ordner_zuruecksetzen'] };
const kiFn = aktion.slice(0, 2), kiAk = aktion.slice(3);
if (/^[a-z]{2}_[a-z_]{1,40}$/.test(aktion) && (KI_FN[kiFn] || []).includes(kiAk)) {
  FN[0] = kiFn; FN[1] = kiAk;
  const kurz = (v, max) => s(v).slice(0, max);
  const kommas = (v, max) => s(v).split(',').map(x => x.trim()).filter(Boolean).slice(0, max);
  const datumW = v => /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(s(v)) ? s(v) : s(v).slice(0, 10);
  if (kiFn === 'kz') {
    if (kiAk === 'angaben_speichern') daten = { talent_id: id9(b.talent_id), themen: langText(b.themen, 1501), ziele: langText(b.ziele, 1501), zielgruppe: langText(b.zielgruppe, 1501), nogos: langText(b.nogos, 1501),
      stunden_pro_woche: kurz(b.stunden_pro_woche, 10) };
    else if (kiAk === 'erstellen' || kiAk === 'ueberarbeitung_anfordern') daten = { talent_id: id9(b.talent_id) };
    else if (kiAk === 'entwurf_speichern') {
      // Kanäle k<i>_* (höchstens 8) und Themenplan t<i>_* (höchstens 15, leere Zeilen entfallen) zu Arrays
      const kanaele = [], plan = [];
      for (let i = 0; i < 8; i++) {
        if (!(('k' + i + '_plattform') in b)) continue;
        const formate = {}; for (const f of ['reel', 'karussell', 'story', 'video', 'bild']) formate[f] = kurz(b['k' + i + '_f_' + f], 10);
        kanaele.push({ plattform: kurz(b['k' + i + '_plattform'], 20), beitraege_pro_woche: kurz(b['k' + i + '_bpw'], 10), formate, hinweis: kurz(b['k' + i + '_hinweis'], 201) });
      }
      for (let i = 0; i < 16; i++) {
        const thema = kurz(b['t' + i + '_thema'], 81), idee = kurz(b['t' + i + '_idee'], 301);
        if (!thema && !idee) continue;
        plan.push({ woche: kurz(b['t' + i + '_woche'], 2), thema, format: kurz(b['t' + i + '_format'], 20), idee });
      }
      daten = { konzept_id: id9(b.konzept_id), positionierung: langText(b.positionierung, 1501), zielgruppe: langText(b.zielgruppe, 1001), kanaele, themenplan: plan.slice(0, 15) };
    } else if (kiAk === 'aktivieren' || kiAk === 'verwerfen') daten = { konzept_id: id9(b.konzept_id) };
    else if (kiAk === 'ziel_speichern') { daten = { kennzahl: kurz(b.kennzahl, 30), plattform: kurz(b.plattform, 20), zielwert: kurz(b.zielwert, 20), von: datumW(b.von), bis: datumW(b.bis) };
      if (id9(b.ziel_id)) daten.ziel_id = id9(b.ziel_id); else daten.konzept_id = id9(b.konzept_id); }
    else daten = { ziel_id: id9(b.ziel_id) };
  } else if (kiFn === 'wf') daten = { talent_id: id9(b.talent_id), kanal: kurz(b.kanal, 20), zeitraum: kurz(b.zeitraum, 12), von: datumW(b.von), bis: datumW(b.bis) };
  else if (kiFn === 'tx') {
    if (kiAk === 'erstellen') { daten = { art: kurz(b.art, 40), eingabe: langText(b.eingabe, 12001) }; if (id9(b.talent_id)) daten.talent_id = id9(b.talent_id); if (id9(b.kampagne_id)) daten.kampagne_id = id9(b.kampagne_id); }
    else if (kiAk === 'speichern') daten = { text_id: id9(b.text_id), titel: kurz(b.titel, 201), text: langText(b.text, 12001) };
    else daten = { text_id: id9(b.text_id) };
  } else if (kiFn === 'ma') daten = { anfrage: langText(b.anfrage, 12001), ausschliessen: [].concat(b.ausschliessen ?? []).map(x => id9(x)).filter(Boolean).slice(0, 50).map(Number) };
  else if (kiFn === 'ms') {
    if (kiAk === 'kriterium_hinzufuegen') {
      // Kriterium "richtung|feld"; Wert aus der Liste (wert_wahl "feld|wert"), sonst Freitext
      const [richtung, feld] = s(b.kriterium).split('|');
      const ww = s(b.wert_wahl), wl = feld && ww.startsWith(feld + '|') ? ww.slice(feld.length + 1) : '';
      daten = { ebene: s(b.ebene) === 'agentur' ? 'agentur' : 'talent', talent_id: id9(b.talent_id), richtung: kurz(richtung, 20), feld: kurz(feld, 30), wert: wl || kurz(b.wert, 121), grund: kurz(b.grund, 301) };
    } else if (kiAk === 'kriterium_entfernen') daten = { kriterium_id: id9(b.kriterium_id) };
    else if (kiAk === 'suche_starten') {
      const ein = {}, aus = {};
      for (const key of Object.keys(b)) {
        const m = key.match(/^(ein|aus)__([a-z_]{1,30})$/); if (!m) continue;
        const w = kommas(b[key], 10); if (w.length) (m[1] === 'ein' ? ein : aus)[m[2]] = w;
      }
      daten = { talent_id: id9(b.talent_id), einschliessen: ein, ausschliessen: aus };
    } else if (kiAk === 'bewerten') daten = { treffer_id: id9(b.treffer_id), bewertung: ['passt', 'passt_nicht'].includes(s(b.bewertung)) ? s(b.bewertung) : '', grund: kurz(b.grund, 301),
      sperren: ['talent', 'agentur'].includes(s(b.sperren)) ? s(b.sperren) : '' };
    else daten = { treffer_id: id9(b.treffer_id) };
  } else if (kiFn === 'me') {
    daten = { art: kurz(b.art, 30), postfach: kurz(b.postfach, 200).toLowerCase(), an: kurz(b.an, 200).toLowerCase(), an_name: kurz(b.an_name, 121),
      datei_ids: Object.keys(b).filter(x => /^datei__[0-9]{1,15}$/.test(x)).map(x => x.slice('datei__'.length)).slice(0, 10) };
    for (const f of ['talent_id', 'kampagne_id', 'text_id']) if (id9(b[f])) daten[f] = id9(b[f]);
  } else if (kiFn === 'kf') daten = { briefing_tag: kurz(b.briefing_tag, 2), briefing_uhrzeit: kurz(b.briefing_uhrzeit, 8), abweichung_prozent: kurz(b.abweichung_prozent, 5),
    marken_anzahl: kurz(b.marken_anzahl, 5), marken_websuchen: kurz(b.marken_websuchen, 5) };
  else if (kiFn === 'ab') {
    daten = kiAk === 'waehlen' ? { art: kurz(b.art, 30) } : { dienst: kurz(b.dienst, 30) };
    if (kiAk === 'dienst_speichern') Object.assign(daten, { wurzel: kurz(b.wurzel, 501), wurzel_name: kurz(b.wurzel_name, 121), site_id: kurz(b.site_id, 501) });
  }
  const zb = s(b.z_b);
  zurueck = { talent: id9(b.z_talent), b: ['konzept', 'wf', 'marken', 'mails', 'texte', 'anfrage', 'zahlen', 'berichte'].includes(zb) ? zb : '', lauf: id9(b.z_lauf), text: id9(b.z_text),
    anfrage: id9(b.z_anfrage), seite: seite4(b.z_seite), kanal: /^([a-z_]{1,20}|k[0-9]{1,9})$/.test(s(b.z_kanal)) ? s(b.z_kanal) : '', zeitraum: /^[a-z0-9]{1,12}$/.test(s(b.z_zeitraum)) ? s(b.z_zeitraum) : '',
    von: /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(s(b.z_von)) ? s(b.z_von) : '', bis: /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(s(b.z_bis)) ? s(b.z_bis) : '',
    anker: /^[a-z0-9-]{1,40}$/.test(s(b.z_anker)) ? s(b.z_anker) : '' };
  if (kiFn === 'kf' || kiFn === 'ab') zurueck = { tm: kiFn === 'kf' ? 'ki' : 'ablage' };
}

// Monatsbericht und Instagram laufen außerhalb der Datenbank-Aktion; ihre Felder kommen einzeln mit
// (Instagram-Geheimnisse nie in "daten", damit sie nicht in der Sitzung landen)
const mb = aktion === 'monatsbericht' ? {
  projekt_id: /^[0-9]{1,12}$/.test(s(b.projekt_id)) ? s(b.projekt_id) : '',
  monat: /^20[0-9]{2}-(0[1-9]|1[0-2])$/.test(s(b.monat)) ? s(b.monat) : '',
  aufgaben_dl: s(b.aufgaben_dl) === 'ja' ? 'ja' : '',
  label: s(b.projekt_label).slice(0, 200)
} : {};
const ig = aktion === 'instagram' ? { ig_app_id: s(b.ig_app_id), ig_secret: s(b.ig_secret), ig_token: s(b.ig_token) } : {};

return [{ json: { token, aktion, daten: JSON.stringify(daten), benutzer: s(b.benutzer).toLowerCase(), h: s(b.h), hc: s(b.hc), ha: s(b.ha), basis: HOST, fn: FN[0], fn_aktion: FN[1], ...(Object.keys(zurueck).length ? { zurueck } : {}), ...mb, ...ig } }];

// Antwort bauen: Weiterleitung zurück auf die Seite, Sitzungs-Cookie setzen oder löschen (Eingang aus allen Aktionswegen)
const SEITE = '/webhook/web';
const F = $('Formular lesen').first().json;
// Stelle auf der Seite (Stefan 17.10.2026): Position, offene Bereiche und Formular aus der Adresse des Formulars wieder anhängen, damit die Seite nicht nach oben springt
const ZQ = $('Aktion').first().json.query || {};
const stelle = ziel => { const y = String(ZQ.zy || ''), o = String(ZQ.zo || ''), f = String(ZQ.zf || ''), t = String(ZQ.zt || '');
  if (!/^[0-9]{1,6}$/.test(y)) return ziel;
  const z = ziel.split('#')[0], s = 'zy=' + y + (/^[0-9]{1,3}(\.[0-9]{1,3}){0,39}$/.test(o) ? '&zo=' + o : '') + (/^[A-Za-z0-9_-]{0,60}~[0-9]{1,3}$/.test(f) ? '&zf=' + f + (/^-?[0-9]{1,5}$/.test(t) ? '&zt=' + t : '') : '');
  return z + (z.includes('?') ? '&' : '?') + s; };
// Nach dem Mailversand („Passwort vergessen“) kommt das Ergebnis der Datenbank aus „Aktion ausführen“
// Startseite: Ergebnis der Prüfung (ally_web_start); der gestartete Ablauf selbst liefert kein r
// Migration 49 (Stefan 18.10.2026): nach KI-Funktionen und Mail-Entwurf laufen "TALENTS KI-Aufträge" bzw. "TALENTS Mail-Entwürfe" (ohne Warten) dazwischen; Ergebnis aus "Aktion ausführen"
const KI_FN = ['kz', 'wf', 'tx', 'ma', 'ms', 'me', 'kf', 'ab'];
const r = (F.aktion === 'passwort_vergessen' ? {} : F.aktion === 'start' && $('Start prüfen').isExecuted ? $('Start prüfen').first().json.r
  : KI_FN.includes(F.fn) && $('Aktion ausführen').isExecuted ? $('Aktion ausführen').first().json.r : $input.first().json.r) || {};
const keks = (wert, alter) => 'ally_sitzung=' + wert + '; Path=' + SEITE + '; Max-Age=' + alter + '; HttpOnly; Secure; SameSite=None';
let ziel = SEITE, cookie = '';
if (F.aktion === 'ungueltig' || r.ungueltig) {
  ziel = SEITE + '?m=ungueltig';
} else if (F.aktion === 'login') {
  if (r.ok === true && /^[0-9a-f]{64}$/.test(String(r.token || ''))) {
    cookie = keks(r.token, Number(r.max_age) || 1800);
    if (r.ziel === 'profil') ziel = SEITE + '?ansicht=einstellungen&bereich=profil';
  } else { ziel = SEITE + '?m=' + (r.code === 'gesperrt' ? 'gesperrt' : 'falsch'); cookie = keks('', 0); }
} else if (F.aktion === 'passwort_vergessen') {
  // Immer dieselbe Antwort, egal ob die Adresse bekannt ist
  ziel = SEITE + '?m=mail';
} else if (F.aktion === 'passwort_neu') {
  if (r.ok === true && /^[0-9a-f]{64}$/.test(String(r.token || ''))) cookie = keks(r.token, Number(r.max_age) || 2592000);
  else {
    let code = ''; try { code = JSON.parse(F.daten).code || ''; } catch (e) {}
    ziel = r.code === 'passwort' && code ? SEITE + '?ansicht=neu&code=' + code + '&m=pwfehler' : SEITE + '?m=link';
  }
} else if (r.abmelden) {
  ziel = SEITE + '?m=abgemeldet'; cookie = keks('', 0);
} else if (r.angemeldet === false) {
  ziel = SEITE + '?m=abgelaufen'; cookie = keks('', 0);
} else {
  // Sitzung bleibt; Cookie mit voller Laufzeit erneuern (die Datenbank entscheidet über die Gültigkeit)
  if (F.token) cookie = keks(F.token, 2592000);
  // Zurück auf die Seite, von der die Aktion kam (Einstellungen: dasselbe Thema); sonst Startseite
  const thema = { funktionen: 'benachrichtigungen', einstellungen: 'profil', postfach: 'postfaecher', unternehmen: 'unternehmen', unternehmen_loeschen: 'unternehmen', cd: 'unternehmen', cd_datei_loeschen: 'unternehmen', startseite: 'startseite', regel_neu: 'regeln', regel_loeschen: 'regeln',
    person_zugang: 'personen', person_sperren: 'personen', person_freigeben: 'personen', person_neu: 'personen', person_rechte: 'personen', person_ally: 'personen',
    person_daten: 'personen', profil: 'profil' }[F.aktion] || { sa: 'superadmin', ki: 'ki', tl: 'talents', mi: 'superadmin', pa: 'superadmin', mr: 'superadmin', kf: 'talents', ab: 'talents' }[F.fn]; // KI und Superadmin, Talents (Stefan 18.10.2026); mi = Meta-App für Instagram-Anmeldung (Stefan 18.10.2026)
  // Seiten der Pakete: zurück auf die Seite, von der gespeichert wurde (Talents: Schalter stehen unter Benachrichtigungen, Stefan 18.10.2026)
  let pk = ''; try { pk = String(JSON.parse(F.daten).paket || ''); } catch (e) {}
  if (!/^[a-z_]{1,30}$/.test(pk)) pk = '';
  // Startseite: zurück auf die Maske, von der gestartet wurde
  let was = ''; try { was = String(JSON.parse(F.daten).was || ''); } catch (e) {}
  const MASKE = { belege: 'belege_verbuchen', abgleich: 'abgleich', themen: 'beitrag', beitrag: 'beitrag', kundenueberblick: 'kundenueberblick', briefing: 'briefing' }[was];
  ziel = F.aktion === 'start' && MASKE ? SEITE + '?ansicht=' + MASKE
    : F.aktion === 'monatsbericht' ? SEITE + '?ansicht=monatsbericht'
    : thema === 'unternehmen' ? SEITE + '?ansicht=unternehmen'
    : F.aktion === 'marketing' || F.aktion === 'cd_gestaltung' || F.aktion === 'hintergrund_loeschen' ? SEITE + '?ansicht=marketing'
    : F.aktion === 'instagram' ? SEITE + '?ansicht=marketing#instagram'
    : F.aktion === 'paket_fuer_mich' ? (pk === 'grundpaket' || pk === 'talents' || !pk ? SEITE + '?ansicht=einstellungen&bereich=benachrichtigungen' : SEITE + '?ansicht=' + pk + '#fuer-mich')
    : (thema ? SEITE + '?ansicht=einstellungen&bereich=' + thema : SEITE);
  // Corporate Design: dasselbe Unternehmen wieder aufklappen und dorthin springen
  if (['cd', 'cd_datei_loeschen', 'cd_gestaltung', 'hintergrund_loeschen'].includes(F.aktion)) {
    let uid = ''; try { uid = String(JSON.parse(F.daten).id || ''); } catch (e) {}
    if (/^[0-9]{1,9}$/.test(uid)) ziel += ['cd_gestaltung', 'hintergrund_loeschen'].includes(F.aktion) ? '#gest-' + uid : '&offen=' + uid + '#cd-' + uid;
  }
  // Talents (Stefan 18.10.2026): mit dem gewählten Talent (talent_id der Datenbank, sonst id aus dem Formular); "Neues Talent" mit Fehler zurück auf die Maske.
  // Nach erfolgreichem Anlegen oder Löschen ist es eine andere Ansicht: dann ohne Stelle (Seite oben, Meldung und Einladungslink oben).
  let andereAnsicht = false;
  if (F.fn === 'tl') {
    let tid = ''; try { tid = String(JSON.parse(F.daten).id || ''); } catch (e) {}
    if (r.ok === true && /^[0-9]{1,9}$/.test(String(r.talent_id ?? ''))) tid = String(r.talent_id);
    if (!/^[0-9]{1,9}$/.test(tid) || F.fn_aktion === 'einstellungen' || (F.fn_aktion === 'talent_loeschen' && r.ok === true)) tid = '';
    // Einfache Ansichten (Stefan 18.10.2026): nach "Einladung erstellen" und "Neuer Link" die Ansicht Einladung (tm=einladung)
    const zurEinladung = r.ok === true && ['talent_neu', 'einladung_neu'].includes(F.fn_aktion);
    // Teil B (Stefan 19.10.2026): Talents verwalten steht im Bereich Talents (Liste, Talent einladen, Stammdaten bzw. Einladungslink des Talents);
    // nur die Standards der Agentur bleiben unter Einstellungen › Talents
    if (F.fn_aktion === 'einstellungen') ziel += '&tm=standards';
    else ziel = SEITE + '?ansicht=talents' + (tid ? '&talent=' + tid + (zurEinladung ? '&tm=einladung' : '&b=stammdaten') : F.fn_aktion === 'talent_neu' && r.ok !== true ? '&tm=neu' : '');
    andereAnsicht = r.ok === true && ['talent_neu', 'einladung_neu', 'talent_loeschen'].includes(F.fn_aktion);
  }
  // Talents-Seiten (Stefan 18.10.2026): nach "Verfolgung für diesen Beitrag" zurück auf die Ansicht des Beitrags (IDs aus der Datenbank, sonst aus dem Formular)
  if (F.fn === 'tb') {
    let d = {}; try { d = JSON.parse(F.daten) || {}; } catch (e) {}
    const tid = /^[0-9]{1,9}$/.test(String(r.talent_id ?? '')) ? String(r.talent_id) : /^[0-9]{1,9}$/.test(String(d.talent || '')) ? String(d.talent) : '';
    const bid = /^[0-9]{1,12}$/.test(String(r.beitrag_id ?? '')) ? String(r.beitrag_id) : /^[0-9]{1,12}$/.test(String(d.beitrag || '')) ? String(d.beitrag) : '';
    ziel = SEITE + '?ansicht=talents' + (tid ? '&talent=' + tid : '') + (bid ? '&b=beitrag&beitrag=' + bid : '');
  }
  // Stufe 2 (Stefan 18.10.2026), Migration 46: Rücksprung nach Notizen (tn), Kampagnen (tk) und Import (ti). IDs aus der Datenbank, sonst aus dem Formular (zurueck).
  const Z = F.zurueck && typeof F.zurueck === 'object' ? F.zurueck : {};
  const ziffern = (v, n) => new RegExp('^[0-9]{1,' + n + '}$').test(String(v ?? '')) ? String(v) : '';
  const anh = o => Object.entries(o).filter(x => x[1]).map(x => '&' + x[0] + '=' + encodeURIComponent(String(x[1]))).join('');
  if (F.fn === 'tn') {
    const tid = ziffern(r.talent_id, 9) || ziffern(Z.talent, 9);
    ziel = SEITE + '?ansicht=talents' + (tid ? '&talent=' + tid + (Z.notizen ? '&b=notizen' + anh({ seite: ziffern(Z.seite, 4) }) : '') : '');
    // neue Notiz: oben auf der Seite der Notizen bzw. beim Block Notizen
    if (r.ok === true && F.fn_aktion === 'notiz_neu') { andereAnsicht = true; ziel += Z.notizen ? '' : '#tv-notizen'; }
  }
  if (F.fn === 'tk') {
    const kid = ziffern(r.kampagne_id, 9) || ziffern(Z.kampagne, 9);
    if (F.fn_aktion === 'kampagne_loeschen' && r.ok === true) { ziel = SEITE + '?ansicht=kampagnen'; andereAnsicht = true; }
    else if (F.fn_aktion === 'kampagne_neu' && r.ok !== true) ziel = SEITE + '?ansicht=kampagnen&tm=neu';
    else if (!kid) ziel = SEITE + '?ansicht=kampagnen';
    else if (F.fn_aktion === 'kampagne_bearbeiten' && r.ok !== true) ziel = SEITE + '?ansicht=kampagnen&kampagne=' + kid + '&b=bearbeiten';
    else if (Z.zuordnen) ziel = SEITE + '?ansicht=kampagnen&kampagne=' + kid + '&b=zuordnen' + anh({ talent: ziffern(Z.talent, 9), bereich: ['zeitraum', 'alle'].includes(Z.bereich) ? Z.bereich : '', seite: ziffern(Z.seite, 4) });
    else ziel = SEITE + '?ansicht=kampagnen&kampagne=' + kid + anh({ vseite: ziffern(Z.vseite, 4), bseite: ziffern(Z.bseite, 4) });
    // nach Anlegen oder Speichern: Seite der Kampagne von oben
    if (r.ok === true && ['kampagne_neu', 'kampagne_bearbeiten'].includes(F.fn_aktion)) andereAnsicht = true;
  }
  if (F.fn === 'ti') {
    const iid = ziffern(r.import_id, 9) || ziffern(Z.import, 9);
    ziel = SEITE + '?ansicht=talents&tm=import' + (iid && !(F.fn_aktion === 'import_verwerfen' && r.ok === true) ? '&import=' + iid : ''); // Teil B (Stefan 19.10.2026): Bereich Talents
    andereAnsicht = true;
  }
  // Migrationen 48–50 (Stefan 18.10.2026): Plattform-Apps und Meta zurück auf ihre Ansicht unter Superadmin (Plattform-Apps an die Karte der Plattform)
  if (F.fn === 'pa' || F.fn === 'mr') {
    let pl = ''; try { pl = String(JSON.parse(F.daten).plattform || ''); } catch (e) {}
    ziel = SEITE + '?ansicht=einstellungen&bereich=superadmin&sa=' + (F.fn === 'pa' ? 'plattformen' + (/^[a-z]{1,20}$/.test(pl) ? '#pa-' + pl : '') : 'meta');
  }
  // Migration 49 (Stefan 18.10.2026): KI-Funktionen (Admin) und Speicherort zurück auf ihre Ansicht; KI-Funktionen der Talents zurück auf die Unteransicht (z_* aus dem Formular).
  // Neu angelegt (Text, Anfrage, Suche): die neue Stelle öffnen (ID aus der Datenbank), Seite von oben.
  if (F.fn === 'kf' || F.fn === 'ab') ziel = SEITE + '?ansicht=einstellungen&bereich=talents&tm=' + (F.fn === 'kf' ? 'ki' : 'ablage');
  if (['kz', 'wf', 'tx', 'ma', 'ms', 'me'].includes(F.fn)) {
    const o = { talent: ziffern(Z.talent, 9), b: Z.b || '', lauf: ziffern(Z.lauf, 9), text: ziffern(Z.text, 9), anfrage: ziffern(Z.anfrage, 9), seite: ziffern(Z.seite, 4),
      kanal: Z.kanal || '', zeitraum: Z.zeitraum || '', von: Z.von || '', bis: Z.bis || '' };
    let anker = /^[a-z0-9-]{1,40}$/.test(String(Z.anker || '')) ? String(Z.anker) : '';
    if (r.ok === true && F.fn === 'ms' && F.fn_aktion === 'suche_starten' && ziffern(r.lauf_id, 9)) { o.lauf = ziffern(r.lauf_id, 9); andereAnsicht = true; }
    if (r.ok === true && F.fn === 'tx' && F.fn_aktion === 'erstellen' && ziffern(r.text_id, 9)) { o.text = ziffern(r.text_id, 9); anker = 'text'; andereAnsicht = true; }
    if (r.ok === true && F.fn === 'tx' && F.fn_aktion === 'loeschen') { o.text = ''; andereAnsicht = true; }
    if (r.ok === true && F.fn === 'ma' && ziffern(r.anfrage_id, 9)) { o.anfrage = ziffern(r.anfrage_id, 9); o.seite = ''; anker = 'anfrage'; andereAnsicht = true; }
    ziel = SEITE + '?ansicht=talents' + (o.b ? anh(o) : '') + (anker ? '#' + anker : '');
  }
  // Sammel-Aktion neue Links: Liste von oben (Hinweis und Tabelle zum Herunterladen stehen oben)
  if (F.fn === 'tl' && F.fn_aktion === 'links_erneuern') andereAnsicht = true;
  if (!andereAnsicht) ziel = stelle(ziel);
}
return [{ json: { ziel, set_cookie: cookie } }];

// Ergebnis des Monatsberichts für die Oberfläche: kurzer Hinweis oben und die Eckdaten (oder der genaue Grund) einmalig in der Sitzung
const F = $('Formular lesen').first().json;
const lief = $('Bericht erstellen (BERICHT 2)').isExecuted;
const r = lief ? (($('Bericht erstellen (BERICHT 2)').first() || {}).json || {}) : {};
const fehlerText = e => String((e && (e.message || e.description)) || e || '').replace(/\s*\[line \d+\]\s*$/, '').trim();
let text, art, ergebnis;
if (!lief) {
  text = 'Bericht nicht erstellt: Bitte Kunde und Projekt wählen.'; art = 'fehler';
  ergebnis = { art: 'monatsbericht', ok: false, label: F.label, grund: 'Es wurde kein Projekt übermittelt.' };
} else if (r.ok === true) {
  text = 'Bericht erstellt: ' + r.titel + ' für ' + r.kunde + ' · ' + r.projekt + '.'; art = 'ok';
  ergebnis = { art: 'monatsbericht', ok: true, titel: r.titel, kunde: r.kunde, projekt: r.projekt, datei: r.datei, ablage: r.ablage, zeitraum: r.zeitraum,
    eintraege: r.eintraege, zeit: r.zeit, stunden: r.stunden, betrag: r.betrag, aufgaben_dl: r.aufgaben_dl || '', preis: r.preis,
    verbraucht_bisher: r.verbraucht_bisher || '', rest: r.rest || '', ueber_budget: !!r.ueber_budget };
} else {
  const grund = fehlerText(r.error) || fehlerText(r.fehler) || 'Unbekannter Fehler. Details stehen in n8n bei der Berichterstellung (BERICHT 2).';
  text = 'Bericht nicht erstellt. Den Grund siehst du unten.'; art = 'fehler';
  ergebnis = { art: 'monatsbericht', ok: false, label: F.label, grund };
}
return [{ json: { token: F.token, text, art, ergebnis: JSON.stringify(ergebnis) } }];

// Instagram-Zugang: kurzlebigen Zugriffsschlüssel gegen einen dauerhaften Seiten-Schlüssel tauschen (wie bisher auf der eigenen Instagram-Seite)
// Ohne feste Werte (17.10.2026): Bevorzugt wird die Facebook-Seite mit dem Namen des eigenen Unternehmens (Einstellungen › Unternehmen), sonst die erste mit Instagram-Konto.
const FIRMA = String($('Recht prüfen (Instagram)').first().json.firma || '').trim();
const norm = t => String(t || '').toLowerCase().replace(/[^a-z0-9äöüß]/g, '');
const f = $('Formular lesen').first().json;
const appId = String(f.ig_app_id || '').trim();
const secret = String(f.ig_secret || '').trim();
const kurz = String(f.ig_token || '').trim();
const G = 'https://graph.facebook.com/v26.0/';
const hole = async (pfad, qs) => {
  const r = await this.helpers.httpRequest({ method: 'GET', url: G + pfad, qs, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true });
  let b = r.body;
  if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) {} }
  return { status: r.statusCode, body: b || {} };
};
const fm = r => ((r.body || {}).error || {}).message || ('Status ' + r.status);
const raus = fehler => [{ json: { ok: false, fehler } }];
if (!appId || !secret || !kurz) return raus('Bitte alle drei Felder ausfüllen.');

const lang = await hole('oauth/access_token', { grant_type: 'fb_exchange_token', client_id: appId, client_secret: secret, fb_exchange_token: kurz });
if (lang.status !== 200 || !lang.body.access_token) return raus('Schlüssel konnte nicht verlängert werden (App-ID, App-Geheimcode und Zugriffsschlüssel prüfen): ' + fm(lang));

const seiten = await hole('me/accounts', { fields: 'name,access_token,instagram_business_account{id,username}', limit: 100, access_token: lang.body.access_token });
if (seiten.status !== 200) return raus('Facebook-Seiten konnten nicht gelesen werden: ' + fm(seiten));
const liste = Array.isArray(seiten.body.data) ? seiten.body.data : [];
const mitIg = liste.filter(s => s.instagram_business_account && s.instagram_business_account.id && s.access_token);
if (!mitIg.length) return raus(liste.length ? 'Gefunden: ' + liste.map(s => s.name).join(', ') + ' – aber keine dieser Seiten ist mit einem Instagram-Konto verknüpft bzw. freigegeben.' : 'Der Schlüssel hat keinen Zugriff auf eine Facebook-Seite. Beim Erzeugen im Graph API Explorer die Facebook-Seite ' + (FIRMA ? '„' + FIRMA + '“ ' : '') + 'und das Instagram-Konto auswählen.');
const s = (FIRMA && (mitIg.find(x => norm(x.name) === norm(FIRMA)) || mitIg.find(x => norm(x.name).includes(norm(FIRMA))))) || mitIg[0];

const dbg = await hole('debug_token', { input_token: s.access_token, access_token: appId + '|' + secret });
const d = (dbg.body && dbg.body.data) || {};
const ablauf = d.expires_at === 0 ? 'läuft nicht ab' : (d.expires_at ? 'gültig bis ' + new Date(d.expires_at * 1000).toLocaleDateString('de-DE', { timeZone: 'Europe/Berlin' }) : 'Ablauf unbekannt');
return [{ json: { ok: true, fehler: '', token: s.access_token, ig_id: String(s.instagram_business_account.id), username: String(s.instagram_business_account.username || ''), seite: s.name, ablauf } }];

// Ergebnis des Instagram-Zugangs für die Oberfläche (der Schlüssel selbst wird nie angezeigt)
const F = $('Formular lesen').first().json;
const t = ($('Instagram-Schlüssel tauschen').first() || {}).json || {};
// Produktname aus der Datenbank (produkt_name() im Knoten "Recht prüfen (Instagram)"), kein fester Name im Code (Stefan 18.10.2026)
const PN = String($('Recht prüfen (Instagram)').first().json.produkt_name || '').trim();
// Gespeichert, wenn alle fünf Firmenwerte zurückkommen (ally_einstellungen, Stefan 17.10.2026)
const NOETIG = ['instagram_token', 'instagram_user_id', 'instagram_username', 'instagram_token_datum', 'instagram_von'];
const zurueck = $('Instagram-Schlüssel speichern').isExecuted ? $('Instagram-Schlüssel speichern').all().map(i => String((i.json || {}).schluessel || '')) : [];
const gespeichert = NOETIG.every(x => zurueck.includes(x));
let text, art;
if (t.ok === true && gespeichert) {
  text = 'Instagram ist verbunden über die Facebook-Seite „' + t.seite + '“ mit @' + t.username + ' (Zugriffsschlüssel ' + t.ablauf + '). Der Zugang gilt für alle. ' + PN + ' postet nur nach Freigabe im Chat.'; art = 'ok';
} else if (t.ok === true) {
  text = 'Der Schlüssel war gültig, konnte aber nicht gespeichert werden. Bitte erneut versuchen.'; art = 'fehler';
} else {
  text = (t.fehler || 'Unbekannter Fehler.') + ' Bitte im Graph API Explorer einen neuen Zugriffsschlüssel erzeugen und erneut speichern.'; art = 'fehler';
}
return [{ json: { token: F.token, text, art, ergebnis: 'null' } }];

