// Teil C (Stefan 19.10.2026): Einstellungen ohne Erklärabsätze (eine Zeile je Karte, Technische Angaben eingeklappt), Begriff Antwortvorschläge.
// Postfächer einsetzen: baut den Bereich "Postfächer" (mit Postfach-Plätzen und Unternehmen-Auswahl), die Seiten "Unternehmen"
// und "Marketing" samt Kacheln und setzt sie in die fertige Seite ein. (Eigener Baustein, damit "Seite bauen" nicht komplett neu geschrieben werden muss.
// Bei der nächsten Überarbeitung von "Seite bauen" dort übernehmen.)
// Pakete: Was nicht gebucht ist, erscheint nicht (nur in der Paket-Übersicht als "zubuchbar").
// Jedes Zusatzpaket hat eine eigene Seite mit "Für mich" und "Für alle"; unter Einstellungen bleiben Mein Konto, Grundpaket und Paket.
let html = $json.html || '';
const ersetzen = (id, neu) => {
  const ANF = '<section class="karte" id="' + id + '">';
  const a = html.indexOf(ANF);
  if (a < 0) return false;
  const e = html.indexOf('</section>', a);
  if (e < 0) return false;
  html = html.slice(0, a) + neu + html.slice(e + '</section>'.length);
  return true;
};
const S = $('Seite laden').first().json.s || {};
