    feld('ort', 'Ort (optional)', t ? t.ort : '') + (t && t.notiz_fest ? versteckt('beschreibung_behalten', '1') + '<p class="klein">Die Notiz hat Formatierungen aus Google Kalender und bleibt beim Ändern, wie sie ist.</p>' : text('beschreibung', 'Notiz (optional)', t ? t.beschreibung : ''));
  const gew = /^[A-Za-z0-9_-]{1,200}$/.test(rq('termin')) ? rq('termin') : '';
