    liste = UI.tabelle([{ titel: 'Termin' }, { titel: 'Tag' }, { titel: 'Zeit' }], b.zeilen.map(t => ({ aktiv: sel === t, zellen: [
      zeile2(UI.zeilenlink(t.titel || '(ohne Titel)', adr(Object.assign({}, basis, { termin: t.id, seite: b.seite > 1 ? b.seite : '' })) + '#termine'), esc(t.ort || '')), esc(tag(t)), esc(t.ganz ? 'ganztägig' : (t.von || '') + '–' + (t.bis || ''))] })),
      seitenAng(b, s => adr(Object.assign({}, basis, { seite: s })) + '#termine', b.n === 1 ? 'Termin' : 'Termine'), { leer: 'Keine Termine in diesem Zeitraum.' });
  }
  const zu = adr(Object.assign({}, basis, { seite: b && b.seite > 1 ? b.seite : '' })) + '#termine';
  let detail = '', ptitel = '';
  if (sel) { ptitel = 'Termin';
    detail = '<h2 class="ui-karte-titel">' + esc(sel.titel || '') + '</h2>' + ((sel.notiz || sel.beschreibung) ? '<div class="ui-text">' + esc(sel.notiz || sel.beschreibung) + '</div>' : '') +
      (sel.link ? '<p class="klein"><a href="' + esc(sel.link) + '" target="_blank" rel="noopener">In Google Kalender öffnen</a></p>' : '') +
      form('termin_aendern', versteckt('termin', sel.id) + tFelder(sel) + knopf('Änderung speichern'), frage('Termin ändern? Teilnehmer werden nicht benachrichtigt.')) +
      '<div style="margin-top:10px">' + form('termin_loeschen', versteckt('termin', sel.id) + knopf('Termin löschen', 'gefahr klein'), frage('Termin „' + sel.titel + '“ löschen?')) + '</div>'; }
  else if (gew === 'neu') { ptitel = 'Neuer Termin';
