  const B = X.budgets || null;
  if (!B) return UI.karte('', '', UI.leer('Die Budgets konnten nicht geladen werden.'));
  if (B.fehler && !LI(B.projekte).length) return UI.karte('', '', '<div class="hinweis fehler">' + esc(B.fehler) + '</div>');
  if (B.keine || !LI(B.projekte).length) return UI.karte('', '', UI.leer('Keine laufenden Projekte mit Budget.'));
  const eur = v => v == null ? '–' : Number(v).toLocaleString('de-DE', { style: 'currency', currency: 'EUR' });
  const std = v => v == null ? '–' : Number(v).toLocaleString('de-DE', { maximumFractionDigits: 1 }) + ' h';
  const b = blatt(B.projekte, 'seite');
  const zeilen = b.zeilen.map(p => { const geld = p.budget_art === 'Geld'; const w = p.prozent != null && p.prozent >= 80;
    return [zeile2('<strong>' + esc(p.projekt) + '</strong>', esc(p.kunde || '') + (p.laufzeit_beendet ? ' · <span style="color:var(--warn);font-weight:700">Laufzeit beendet</span>' : '')), geld ? eur(p.budget_eur) : std(p.budget_stunden),
      geld ? zeile2(eur(p.verbraucht_eur), std(p.stunden)) : std(p.stunden), p.prozent == null ? '–' : UI.status(String(p.prozent).replace('.', ',') + ' %', w ? 'warn' : 'info'), geld ? eur(p.rest_eur) : std(p.rest_stunden)]; });
  return UI.karte('Laufende Projekte mit Budget', 'Stand ' + (B.stand || '') + (B.grundlage ? ' · ' + B.grundlage : ''), (B.fehler ? '<div class="hinweis fehler">' + esc(B.fehler) + '</div>' : '') +
    UI.tabelle([{ titel: 'Projekt' }, { titel: 'Budget', rechts: true }, { titel: 'Verbraucht', rechts: true }, { titel: 'Anteil', rechts: true }, { titel: 'Rest', rechts: true }], zeilen,
      seitenAng(b, s => adr({ ansicht: 'budgets', seite: s }), b.n === 1 ? 'Projekt' : 'Projekte')), [], { id: 'budgets' });
}

