// Plan 51 / Migration 189 (Koordinator 31.10.2026): Buchungen ohne Preis zeigen „Kosten unbekannt“ statt 0 €; Summen mit einem unbekannten Teil zeigen den
// bekannten Betrag mit dem Zusatz „dazu N Aufrufe ohne Preis (Kosten unbekannt)“. ohne_preis/aufrufe kommen aus der Datenbank (Migration 189).
const KU_n = x => Math.max(0, Number((x || {}).ohne_preis) || 0);
const KU_alle = x => KU_n(x) > 0 && KU_n(x) >= (Number((x || {}).aufrufe) || 0);
const KU_t = n => n.toLocaleString('de-DE') + (n === 1 ? ' Aufruf' : ' Aufrufe') + ' ohne Preis';
const KU_dazu = n => 'dazu ' + KU_t(n) + ' (Kosten unbekannt)';
const KU_wert = (x, betrag) => KU_alle(x) ? 'Kosten unbekannt (' + KU_t(KU_n(x)) + ')' : KU_n(x) ? betrag + ' · ' + KU_dazu(KU_n(x)) : betrag;
// KI und Superadmin einsetzen (Stefan 18.10.2026): eigener Baustein am Ende der Seitenkette (nach "Arbeitsbereiche einsetzen"), damit die großen
// Bausteine unverändert bleiben. Bei der nächsten Überarbeitung von "Seite bauen" / "Postfächer einsetzen" / "Startseite einsetzen" dort übernehmen.
// - Einstellungen › KI (Admins) und › Superadmin (nur Superadmins): Menüpunkte, Inhalt, Seitentitel. Ohne Recht: weder Menüpunkt noch Inhalt, nur ein Hinweis.
// - Personen und Rechte: Kennzeichen "Superadmin", bei geschützten Personen (geschuetzt) keine Formulare.
// - KI-Verbrauch: Text zu Kundenpreisen, Hinweis bei eigenem Anthropic-Schlüssel (stand.informativ), Euro je Funktion aus funktionen[].eur.
// - Gebuchte Pakete: Satz mit dem Anbieternamen aus der Datenbank, für Superadmins Link zum Bereich Superadmin.
let html = $json.html || '';
const S = $('Seite laden').first().json.s || {};
const n = S.nutzer || {}, D = S.daten || {}, R = n.rechte || [];
const Q = $('Anfrage lesen').first().json || {};
const SEITE = '/webhook/web';
const AKTION = '/webhook/web/aktion';
const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const PN = String($('Seite laden').first().json.produkt_name || '').trim(), PNE = esc(PN);
const mitName = t => (PN ? PN + ' – ' : '') + t;
const darf = r => R.includes(r);
const sw = (name, an, label) => '<label class="schalter"><input type="checkbox" name="' + esc(name) + '" value="1"' + (an ? ' checked' : '') + ' aria-label="' + esc(label) + '"><span></span></label>';
const form = (aktion, inner, extra) => '<form method="POST" action="' + AKTION + '"' + (extra || '') + '><input type="hidden" name="aktion" value="' + aktion + '">' + inner + '</form>';
const frage = t => ' data-frage="' + esc(t) + '"';
if (!S.angemeldet || S.muss_pw_setzen) return [{ json: $json }];
// KI und Superadmin (Stefan 18.10.2026): Einstellungen › KI (Admins) und Einstellungen › Superadmin (nur Superadmins).
// Daten: ki_web_daten bzw. superadmin_web_daten aus "Seite laden" (Felder kd und sd, nur in diesen beiden Bereichen abgerufen).
// Formulare sa_* gehen an superadmin_web_aktion, ki_modelle an ki_web_aktion (Zuordnung in "Formular lesen").
// Der Anthropic-Schlüssel geht an den eigenen Ablauf KI-Zugang (/ki-zugang, Muster Papierkram) und wird nie angezeigt.
// Keine festen Modellnamen oder Preise: Modelle, Preise, Schwellen und Namen kommen aus der Datenbank.
const SL = $('Seite laden').first().json;
const KD = SL.kd && typeof SL.kd === 'object' ? SL.kd : null, SD = SL.sd && typeof SL.sd === 'object' ? SL.sd : null;
const KI_ZIEL = '/webhook/web/ki-zugang';
const istZahl = v => v !== null && v !== undefined && v !== '' && isFinite(Number(v));
const zahlDe = (v, st) => istZahl(v) ? Number(v).toLocaleString('de-DE', { minimumFractionDigits: st, maximumFractionDigits: st }) : '';
// Werte in Eingabefeldern ohne Tausenderpunkt (die Datenbank liest 49,90 oder 1,3)
const zahlFeld = (v, st) => istZahl(v) ? Number(v).toLocaleString('de-DE', { minimumFractionDigits: st, maximumFractionDigits: Math.max(st, 4), useGrouping: false }) : '';
// Preis je 1 Mio. Tokens: kleine Beträge mit mehr Stellen
const preis = v => istZahl(v) ? Number(v).toLocaleString('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: Math.abs(Number(v)) < 0.1 ? 4 : 2 }) : '–';
const preisPaar = (o, w) => o && typeof o === 'object' ? preis(o.eingabe) + ' / ' + preis(o.ausgabe) + ' ' + w : '–';
const schwelle = m => istZahl(m.schwelle_tokens) && istZahl(m.faktor_ueber_schwelle)
  ? 'Bei sehr langen Anfragen (über ' + zahlDe(m.schwelle_tokens, 0) + ' Tokens) gilt der ' + Number(m.faktor_ueber_schwelle).toLocaleString('de-DE', { maximumFractionDigits: 2 }) + '-fache Preis.' : '';
const LINK = ' style="color:var(--akzentDunkel);font-weight:700"';
const sofortKnopf = '<noscript><button class="klein" type="submit">Speichern</button></noscript>';
const KEIN = Q.bereich === 'superadmin' && !darf('superadmin') ? String((SD && SD.fehler) || 'Diese Seite ist nur für Superadmins.')
  : Q.bereich === 'ki' && !darf('admin') ? String((KD && KD.fehler) || 'Die KI-Einstellungen ändert ein Admin.') : '';
