  const hinweise = ML.filter(m => schwelle(m)).map(m => '<p class="klein">' + esc(m.name) + ': ' + esc(schwelle(m)) + '</p>').join('');
  const modelle = '<section class="karte" id="ki"><h2>KI-Modelle</h2><p class="unter">Welches Claude-Modell für welche Aufgaben genutzt wird.</p>' + sparHinweis((KD.stand && typeof KD.stand === 'object' ? KD.stand : null) || (D.ki || {}).stand) +
    (ML.length ? form('ki_modelle',
      '<div class="zwei"><div><label class="feld" for="ki-einfach">Einfache Aufgaben</label>' + wahl('einfach', KD.modell_einfach) +
      '<p class="klein">Mails einordnen, Zusammenfassungen, Belege lesen.</p></div>' +
      '<div><label class="feld" for="ki-anspruchsvoll">Anspruchsvolle Aufgaben</label>' + wahl('anspruchsvoll', KD.modell_anspruchsvoll) +
      '<p class="klein">Chat, Mail-Entwürfe, Marketing-Themen und -Beiträge.</p></div></div>' +
      '<p class="klein">Preise je 1 Mio. Tokens in ' + (euro ? 'Euro' : 'Dollar') + ': Eingabe / Ausgabe</p>' + hinweise +
      '<button type="submit">Modelle speichern</button>')
      : '<p class="leer">Es ist noch kein Modell freigegeben.</p>') +
    technik('<p>Eingabe ist der Text an die KI, Ausgabe ihre Antwort.' + (euro && istZahl(KD.kurs) ? ' Umgerechnet mit dem Referenzkurs der Europäischen Zentralbank' + (KD.kurs_stand ? ' vom ' + esc(KD.kurs_stand) : '') + '.' : '') + '</p>');
  const kunde = KD.ki_schluessel === 'kunde';
  const stand = '<div class="zeile"><div class="text"><strong>' + (kunde ? 'Eigener Anthropic-Schlüssel' : (AN ? 'KI-Zugang von ' + esc(AN) : 'KI-Zugang eures Anbieters')) + '</strong><span>' +
    (kunde ? 'Anthropic rechnet die KI-Kosten direkt mit euch ab.' : 'Die KI läuft über den Anthropic-Zugang ' + (AN ? 'von ' + esc(AN) : 'eures Anbieters') + '.') +
    (KD.zugang_geprueft ? ' Zuletzt geprüft: ' + esc(KD.zugang_geprueft) + ' Uhr.' : '') + '</span></div><span class="marke an">' + (kunde ? 'eigener Schlüssel' : 'Anbieter') + '</span></div>';
  // Karte KI-Zugang nur, wenn diese Person den Schlüssel ändern darf; sonst steht der Zugang als Zeile unter den Modellen
  if (KD.darf_schluessel_aendern !== true) return modelle + '<div style="margin-top:14px">' + stand + '</div><p class="klein">Eigenen Schlüssel schaltet ' + (AN ? esc(AN) : 'euer Anbieter') + ' frei.</p></section>';
  const zugang = '<section class="karte" id="ki-zugang"><h2>KI-Zugang</h2><p class="unter">Anthropic-Schlüssel für alle KI-Aufgaben.</p>' + stand +
