  const personen = '<section class="karte" id="sa-personen"><h2>Personen</h2><p class="unter">Admin- und Superadmin-Rechte. Neue Personen: <a' + LINK + ' href="' + SEITE + '?ansicht=einstellungen&bereich=personen">Personen und Rechte</a></p>' +
    (PE.length ? '<div class="tabelle"><table><thead><tr><th>Person</th><th class="r">Admin</th><th class="r">Superadmin</th></tr></thead><tbody>' +
