        '<td class="r">' + (p.ich && p.admin === true ? '<label class="schalter" title="Das eigene Admin-Recht lässt sich nicht entziehen."><input type="checkbox" checked disabled aria-label="' + esc('Admin: ' + p.name) + '"><span></span></label>'
          : sofort('sa_person_admin', '<input type="hidden" name="id" value="' + esc(p.id) + '">' + sw('admin', p.admin === true, 'Admin: ' + p.name))) + '</td>' +
        // Migration 168 (Bauplan B7, G1): Superadmin nur für Personen aus der Liste superadmin_personen; sonst Schalter gesperrt (Muster wie das eigene Admin-Recht)
        '<td class="r">' + (p.superadmin_moeglich === false ? '<label class="schalter" title="Das Recht Superadmin lässt sich hier nicht vergeben."><input type="checkbox"' + (p.superadmin === true ? ' checked' : '') + ' disabled aria-label="' + esc('Superadmin: ' + p.name) + '"><span></span></label>'
          : sofort('sa_person_superadmin', '<input type="hidden" name="id" value="' + esc(p.id) + '">' + sw('superadmin', p.superadmin === true, 'Superadmin: ' + p.name))) + '</td></tr>').join('') +
      '</tbody></table></div>' : '<p class="leer">Keine Personen.</p>') + technik('<p>Admins haben alle Rechte außer Superadmin, Superadmins haben alle Rechte.</p>') + '</section>';
  // Monat: echte Kosten, Kundenpreis, Anteil, Aufrufe mit eigenem Schlüssel des Kunden (Dollar und Euro)
  const MN = SD.monat && typeof SD.monat === 'object' ? SD.monat : {};
