// Schalter in Tabellen speichern sofort (ohne Skript: Knopf "Speichern")
const SA_SKRIPT = '<script>document.querySelectorAll("form[data-sofort]").forEach(function (f) { f.addEventListener("change", function () { if (f.requestSubmit) f.requestSubmit(); else f.submit(); }); });</script>';


// Teil C (Stefan 19.10.2026): kurze Beschreibungen, Erklärungen unter "Technische Angaben"; Formulare, Felder und Aktionen unverändert.
// Einstellungen: Menüpunkte KI (nach "Personen und Rechte") und Superadmin (nach "Gebuchte Pakete"), Inhalt anstelle des Standardbereichs
if (Q.ansicht === 'einstellungen') {
  const na = html.indexOf('<nav class="themen" aria-label="Einstellungen">'), ne = na >= 0 ? html.indexOf('</nav>', na) : -1;
  if (na >= 0 && ne > na) {
    let nv = html.slice(na, ne);
    const eigen = [];
    if (darf('admin')) eigen.push(['ki', 'KI', /<a href="\/webhook\/web\?ansicht=einstellungen&bereich=personen"[^>]*>[^<]*<\/a>/]);
    if (darf('superadmin')) eigen.push(['superadmin', 'Superadmin', /<a href="\/webhook\/web\?ansicht=einstellungen&bereich=paket"[^>]*>[^<]*<\/a>/]);
    const akt = eigen.find(x => x[0] === Q.bereich) || null;
    if (akt) nv = nv.replace(' class="aktiv" aria-current="page"', '');
    for (const [k, name, nach] of eigen) {
      const a = '<a href="' + SEITE + '?ansicht=einstellungen&bereich=' + k + '"' + (akt && akt[0] === k ? ' class="aktiv" aria-current="page"' : '') + '>' + esc(name) + '</a>';
      const m = nv.match(nach);
      nv = m ? nv.replace(m[0], () => m[0] + a) : nv.replace(/<span class="themen-trenner"><\/span>/, x => a + x);
    }
    html = html.slice(0, na) + nv + html.slice(ne);
    // Inhalt: "Postfächer einsetzen" setzt für unbekannte Bereiche die Benachrichtigungen ein; diese Karte wird ersetzt
    const ANF = '<section class="karte" id="benachrichtigungen">';
    const a = html.indexOf(ANF), e = a >= 0 ? html.indexOf('</section>', a) : -1;
    if (a >= 0 && e > a) {
      if (akt) {
        html = html.slice(0, a) + (akt[0] === 'ki' ? kiSeite() : saSeite()) + html.slice(e + '</section>'.length);
        html = html.replace(/<title>[^<]*<\/title>/, () => '<title>' + esc(mitName('Einstellungen – ')) + esc(akt[1]) + '</title>');
        if (akt[0] === 'superadmin') html = html.replace('</head>', () => SA_STIL + '</head>').replace('</body>', () => SA_SKRIPT + '</body>');
      } else if (KEIN) html = html.slice(0, a) + '<div class="hinweis fehler">' + esc(KEIN) + '</div>' + html.slice(a);
    }
  }
  // Gebuchte Pakete: Anbietername aus der Datenbank (anbieter_name() in "Seite laden"); Superadmins ändern Pakete selbst
  const ALT = 'Pakete ändert euer ' + PNE + '-Betreuer.</p>';
  if (Q.bereich === 'paket' && html.includes(ALT)) {
    const AN = String($('Seite laden').first().json.anbieter_name || '').trim();
    html = html.replace(ALT, () => (AN ? 'Pakete ändert ' + esc(AN) + '.' : 'Pakete ändert euer Anbieter.') +
