  }
  // Personen und Rechte: je Person ein aufklappbarer Bereich in der Reihenfolge von daten.personen
  const PS = Array.isArray(D.personen) ? D.personen : [];
  const pa = Q.bereich === 'personen' ? html.indexOf('<section class="karte" id="personen">') : -1, pe = pa >= 0 ? html.indexOf('</section>', pa) : -1;
  if (pa >= 0 && pe > pa && PS.some(p => p.superadmin === true || p.geschuetzt === true)) {
    const teile = html.slice(pa, pe).split('<details class="postfach">');
    if (teile.length - 1 === PS.length) {
      const neu = teile.slice(1).map((t, i) => {
        const p = PS[i];
        let x = t;
        if (p.superadmin === true) x = x.replace('</h3>', ' <span class="marke">Superadmin</span></h3>');
        if (p.geschuetzt === true) {
