// KI-Verbrauch: Beträge sind Kundenpreise; bei eigenem Anthropic-Schlüssel nur zur Information
if (Q.ansicht === 'verbrauch' && D.ki) {
  const st = D.ki.stand || {};
  const ALT = '<p class="unter">Kosten aller erfassten KI-Aufrufe in diesem Monat, berechnet mit den Listenpreisen von Anthropic. Maßgeblich ist die Rechnung von Anthropic.</p>';
  // Budget-Sperre (Stefan 18.10.2026): Stufe 'gesperrt' aus ki_monat_stand (nur im Modus Sperre) als gut sichtbarer Hinweis über den Werten
  const SPERRE = st.stufe === 'gesperrt' ? '<div class="hinweis fehler"><strong>KI-Aufgaben sind bis zum Monatsende gestoppt, weil das Budget erreicht ist.</strong></div>' : '';
  html = html.replace(ALT, () => '<p class="unter">Kosten aller erfassten KI-Aufrufe in diesem Monat.</p>' + SPERRE + sparHinweis(st) + (st.informativ === true
    ? '<div class="hinweis ok">Eigener Anthropic-Schlüssel: Anthropic rechnet direkt mit euch ab, die Werte sind zur Information.</div>' : ''));
  // Euro je Funktion aus funktionen[].eur (Datenbank), sonst bleibt die Umrechnung der Seite
  const FN = Array.isArray(D.ki.funktionen) ? D.ki.funktionen : [];
  const ta = html.indexOf('<h2>Nach Funktion</h2>'), tb = ta >= 0 ? html.indexOf('<tbody>', ta) : -1, te = tb >= 0 ? html.indexOf('</tbody>', tb) : -1;
  if (tb >= 0 && te > tb) {
    const zeilen = html.slice(tb + 7, te).split('</tr>');
    if (zeilen.length - 1 === FN.length) {
      const neu = zeilen.map((z, i) => i < FN.length && istZahl(FN[i].eur) && !KU_n(FN[i]) ? z.replace(/<br><span class="klein">[^<]*<\/span><\/td>$/, () => '<br><span class="klein">' + zahlDe(FN[i].eur, 2) + ' €</span></td>') : z);
      html = html.slice(0, tb + 7) + neu.join('</tr>') + html.slice(te);
    }
  }
}
// Budget-Marken (Stefan 18.10.2026): "Seite bauen" nennt feste 80 % / 95 %, die Schwellen sind aber einstellbar (warn_prozent, spar_prozent).
// Neutral ersetzt, nur an den zwei Stellen: Zeile "Stand" auf KI-Verbrauch und Kachel "KI-Verbrauch" auf der Startseite.
if (D.ki) {
  for (const [alt, neu] of [['80 % des Budgets erreicht', 'Warnschwelle erreicht'], ['95 % des Budgets erreicht', 'Sparmodus aktiv']]) {
    if (Q.ansicht === 'verbrauch') html = html.replace(new RegExp('(<span class="k">Stand</span><span class="v"><span class="marke [a-z]*">)' + alt + '(</span>)'), (m, a1, a2) => a1 + neu + a2);
    html = html.replace(new RegExp('(<strong>KI-Verbrauch</strong><span>Diesen Monat [^<]*\\. )' + alt + '(\\.</span></a>)'), (m, a1, a2) => a1 + neu + a2);
  }
